  <!-- TOAST NOTIFICATION -->
  <div id="toast" class="fixed bottom-5 right-5 z-50 hidden bg-slate-900 text-white text-xs px-4 py-2.5 rounded-xl shadow-xl border border-slate-700 flex items-center space-x-2 transition-all">
    <i id="toast-icon" class="fa-solid fa-check text-emerald-400"></i>
    <span id="toast-msg">Notifikasi</span>
  </div>

  <script>
    const DIMENSI_RPP_PM = [
      {
        dimensi: 1,
        nama: 'Dimensi 1 — Identifikasi dan kesiapan pembelajaran',
        fokus: 'Apakah rancangan berangkat dari kondisi nyata murid dan karakteristik materi?',
        maxSkor: 12,
        pertanyaanPenelaah: 'Apakah guru merancang pembelajaran berdasarkan apa yang perlu dipelajari murid dan kondisi mereka, atau hanya berdasarkan kebiasaan mengajar?',
        indikator: [
          { id: 1, text: 'CP dan tujuan pembelajaran yang dipilih relevan dengan fase, mata pelajaran, dan materi yang direncanakan.' },
          { id: 2, text: 'Kesiapan awal murid diidentifikasi berdasarkan pengetahuan prasyarat, pengalaman, kebutuhan, atau hasil asesmen awal yang relevan.' },
          { id: 3, text: 'Karakteristik materi dianalisis, termasuk konsep kunci, keterkaitan antarkonsep, potensi miskonsepsi, dan tuntutan berpikir.' },
          { id: 4, text: 'Dimensi profil lulusan yang ditargetkan dipilih secara relevan dan diterjemahkan ke dalam pengalaman belajar, bukan hanya dicantumkan.' }
        ]
      },
      {
        dimensi: 2,
        nama: 'Dimensi 2 — Desain pembelajaran dan keselarasan tujuan',
        fokus: 'Keselarasan antara tujuan, praktik pedagogis, materi, dan bukti keberhasilan.',
        maxSkor: 12,
        pertanyaanPenelaah: 'Jika murid berhasil mengikuti seluruh aktivitas, apakah keberhasilan itu benar-benar menunjukkan bahwa tujuan pembelajaran tercapai?',
        indikator: [
          { id: 5, text: 'Tujuan pembelajaran dirumuskan secara spesifik, realistis, dan menggambarkan kompetensi yang dapat ditunjukkan murid.' },
          { id: 6, text: 'Tujuan pembelajaran selaras dengan aktivitas belajar dan asesmen yang direncanakan.' },
          { id: 7, text: 'Praktik pedagogis atau strategi pembelajaran dipilih sesuai tujuan, karakteristik materi, dan kesiapan murid.' },
          { id: 8, text: 'Alokasi waktu, sumber belajar, media, serta urutan kegiatan realistis dan mendukung pencapaian tujuan.' }
        ]
      },
      {
        dimensi: 3,
        nama: 'Dimensi 3 — Prinsip berkesadaran, bermakna, dan menggembirakan',
        fokus: 'Bagaimana prinsip PM diwujudkan dalam desain pengalaman belajar.',
        maxSkor: 12,
        catatanAhli: 'Menggembirakan tidak identik dengan permainan atau suasana selalu ramai. Pembelajaran yang menantang, membutuhkan ketekunan, dan memicu rasa ingin tahu juga dapat menggembirakan apabila murid merasa dihargai dan memperoleh dukungan.',
        indikator: [
          { id: 9, text: 'Rancangan membantu murid memahami tujuan belajar, kriteria keberhasilan, serta cara memantau kemajuan belajarnya.' },
          { id: 10, text: 'Aktivitas menghubungkan pengetahuan awal dengan konsep baru dan/atau persoalan nyata yang relevan bagi murid.' },
          { id: 11, text: 'Rancangan menyediakan tantangan yang sesuai, pilihan atau ruang partisipasi, serta kesempatan bagi murid untuk mengalami keberhasilan dan belajar dari kesalahan.' },
          { id: 12, text: 'Rancangan menciptakan suasana positif, aman, menghargai perbedaan, dan mendorong keberanian bertanya serta mengemukakan pendapat.' }
        ]
      },
      {
        dimensi: 4,
        nama: 'Dimensi 4 — Pengalaman belajar mendalam',
        fokus: 'Apakah murid memperoleh kesempatan memahami, mengaplikasi, dan merefleksi?',
        maxSkor: 18,
        pertanyaanPenelaah: 'Apakah murid hanya mengetahui jawaban yang benar, atau juga dapat menjelaskan mengapa jawaban itu benar, menggunakannya dalam situasi lain, dan merefleksikan proses berpikirnya?',
        indikator: [
          { id: 13, text: 'Tahap memahami dirancang agar murid membangun pemahaman konsep, menjelaskan dengan kata-kata sendiri, menghubungkan gagasan, atau mengidentifikasi miskonsepsi.' },
          { id: 14, text: 'Tahap mengaplikasi memberi kesempatan menggunakan pengetahuan atau keterampilan untuk menyelesaikan masalah, menguji gagasan, menghasilkan karya, atau menghadapi konteks baru.' },
          { id: 15, text: 'Tahap merefleksi membantu murid menilai pemahamannya, mengenali kesulitan, dan menentukan perbaikan atau strategi belajar berikutnya.' },
          { id: 16, text: 'Aktivitas mendorong penalaran, argumentasi berbasis bukti, kreativitas, pemecahan masalah, atau transfer pengetahuan sesuai tujuan pembelajaran.' },
          { id: 17, text: 'Pertanyaan dan tugas menuntut murid berpikir, membuat keputusan, menjelaskan alasan, atau menghasilkan sesuatu; tidak didominasi kegiatan menyalin dan menghafal tanpa pemahaman.' },
          { id: 18, text: 'Urutan pengalaman belajar menunjukkan hubungan yang logis dan memberi ruang pendalaman, bukan sekadar tiga label tahap yang ditempelkan pada kegiatan.' }
        ]
      },
      {
        dimensi: 5,
        nama: 'Dimensi 5 — Kerangka pembelajaran dan dukungan ekosistem',
        fokus: 'Apakah dukungan pedagogis, lingkungan, kemitraan, dan teknologi dirancang secara fungsional?',
        maxSkor: 12,
        catatanAhli: 'Kemitraan tidak harus selalu menghadirkan narasumber dari luar sekolah, dan teknologi digital bukan kewajiban pada setiap pertemuan. Yang dinilai adalah ketepatan pemilihan dan kontribusinya terhadap pembelajaran.',
        indikator: [
          { id: 19, text: 'Interaksi guru–murid dan antarmurid dirancang untuk mendukung dialog, kolaborasi, pemberian alasan, dan konstruksi pemahaman.' },
          { id: 20, text: 'Lingkungan fisik, sosial, dan emosional mendukung keterlibatan, keselamatan, aksesibilitas, dan penghargaan terhadap keberagaman murid.' },
          { id: 21, text: 'Kemitraan dengan teman sebaya, orang tua, komunitas, atau pihak lain direncanakan apabila relevan dengan tujuan pembelajaran.' },
          { id: 22, text: 'Media dan teknologi digital digunakan jika memberi nilai tambah yang jelas bagi pemahaman, eksplorasi, kolaborasi, atau asesmen.' }
        ]
      },
      {
        dimensi: 6,
        nama: 'Dimensi 6 — Asesmen dan tindak lanjut',
        fokus: 'Apakah asesmen menjadi bagian dari siklus pembelajaran, bukan sekadar tes di akhir.',
        maxSkor: 24,
        pertanyaanPenelaah: 'Apabila hasil asesmen menunjukkan sebagian besar murid belum memahami konsep, apakah rancangan menjelaskan apa yang akan dilakukan guru selanjutnya?',
        indikator: [
          { id: 23, text: 'Asesmen awal direncanakan untuk memperoleh informasi yang diperlukan tentang kesiapan atau kebutuhan belajar murid.' },
          { id: 24, text: 'Asesmen formatif selama proses pembelajaran dirancang untuk mengungkap pemahaman, kesulitan, miskonsepsi, atau kemajuan murid.' },
          { id: 25, text: 'Asesmen akhir menyediakan bukti ketercapaian tujuan pembelajaran yang sesuai dengan kompetensi yang ditargetkan.' },
          { id: 26, text: 'Teknik dan instrumen asesmen sesuai dengan tujuan: pengetahuan, penalaran, keterampilan, proses, atau produk dinilai melalui bukti yang tepat.' },
          { id: 27, text: 'Kriteria keberhasilan atau rubrik cukup jelas sehingga kualitas jawaban, proses, atau produk dapat dinilai secara konsisten dan transparan.' },
          { id: 28, text: 'Rancangan memberi ruang umpan balik yang spesifik, konstruktif, dan dapat digunakan murid untuk memperbaiki hasil belajarnya.' },
          { id: 29, text: 'Tindak lanjut direncanakan berdasarkan hasil asesmen, misalnya pengajaran ulang, bantuan terarah, latihan lanjutan, atau pengayaan.' },
          { id: 30, text: 'Asesmen mempertimbangkan keadilan, aksesibilitas, dan kebutuhan murid tanpa menurunkan esensi kompetensi yang hendak dicapai.' }
        ]
      }
    ];

    const ASPEK_BK_TELAAH = [
      { id: 1, text: 'Modul layanan memuat identitas, topik, sasaran, dan alokasi waktu yang jelas.' },
      { id: 2, text: 'Topik layanan didasarkan pada kebutuhan nyata atau hasil asesmen kebutuhan murid.' },
      { id: 3, text: 'Tujuan layanan dirumuskan secara spesifik dan berorientasi pada perkembangan murid.' },
      { id: 4, text: 'Materi relevan dengan kehidupan murid dan tantangan perkembangannya.' },
      { id: 5, text: 'Kegiatan dirancang untuk membangun kesadaran diri, pengenalan emosi, dan pemahaman kebutuhan diri.' },
      { id: 6, text: 'Kegiatan memberikan kesempatan kepada murid untuk mencoba strategi atau menerapkannya dalam kehidupan nyata.' },
      { id: 7, text: 'Kegiatan menyediakan ruang refleksi terhadap pengalaman, pilihan, dan perilaku murid.' },
      { id: 8, text: 'Metode layanan mendorong partisipasi aktif, dialog, dan interaksi yang sehat.' },
      { id: 9, text: 'Media dan teknologi dipilih sesuai tujuan layanan, kebutuhan, serta karakteristik murid.' },
      { id: 10, text: 'Layanan memperhatikan perbedaan karakteristik, kebutuhan, dan kondisi murid.' },
      { id: 11, text: 'Guru merencanakan suasana layanan yang aman, nyaman, inklusif, dan bebas dari pelabelan.' },
      { id: 12, text: 'Asesmen atau evaluasi dirancang untuk mengetahui ketercapaian tujuan layanan.' },
      { id: 13, text: 'Modul menyediakan tindak lanjut sesuai hasil evaluasi dan kebutuhan murid.' },
      { id: 14, text: 'Terdapat upaya menghubungkan layanan dengan dukungan wali kelas, orang tua, atau pihak lain bila diperlukan.' }
    ];

    const PRINSIP_BK_DL = [
      { key: 'berkesadaran', title: 'Berkesadaran', pemantik: 'Bagaimana murid mengenali diri, emosi, kebutuhan, kekuatan, dan pilihan perilakunya?' },
      { key: 'bermakna', title: 'Bermakna', pemantik: 'Bagaimana materi terhubung dengan pengalaman serta persoalan nyata yang dihadapi murid?' },
      { key: 'merefleksi', title: 'Merefleksi', pemantik: 'Bagaimana murid menilai pengalaman, perkembangan, dan langkah perbaikan berikutnya?' }
    ];

    const SIKLUS_BK_DL = [
