    function saveUserSession(user) {
      if (!user) return;
      currentLoggedInUser = user;
      try {
        localStorage.setItem(STORAGE_KEY_USER, JSON.stringify(user));
      } catch (e) {
        console.warn('Gagal menyimpan session user:', e);
      }
    }

    function clearUserSession() {
      currentLoggedInUser = null;
      try {
        localStorage.removeItem(STORAGE_KEY_USER);
        localStorage.removeItem(STORAGE_KEY_VIEW);
        localStorage.removeItem(STORAGE_KEY_SELECTED_GURU);
      } catch (e) {
        console.warn('Gagal menghapus session user:', e);
      }
    }

    function loadUserSession() {
      try {
        const saved = localStorage.getItem(STORAGE_KEY_USER);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && (parsed.nip || parsed.nama)) {
            currentLoggedInUser = parsed;
            return parsed;
          }
        }
      } catch (e) {
        console.warn('Gagal memuat session user:', e);
      }
      return null;
    }

    function saveDataToLocalStorage() {
      try {
        localStorage.setItem(STORAGE_KEY_GURU, JSON.stringify(guruDatabase));
        localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(appSettings));
      } catch (e) {
        console.warn('Gagal menyimpan ke localStorage:', e);
      }
    }

    function loadDataFromLocalStorage() {
      try {
        const savedSettings = localStorage.getItem(STORAGE_KEY_SETTINGS);
        if (savedSettings) {
          appSettings = JSON.parse(savedSettings);
        }
        const savedGuru = localStorage.getItem(STORAGE_KEY_GURU);
        if (savedGuru) {
          const parsed = JSON.parse(savedGuru);
          if (Array.isArray(parsed) && parsed.length > 0) {
            guruDatabase = parsed;
            return true;
          }
        }
      } catch (e) {
        console.warn('Gagal memuat dari localStorage:', e);
      }
      return false;
    }

    let isServerOnline = false;

    async function apiCall(action, data = null) {
      try {
        const options = {
          method: data ? 'POST' : 'GET',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'same-origin'
        };
        if (data) options.body = JSON.stringify(data);
        const res = await fetch(`api.php?action=${action}`, options);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const json = await res.json();
        updateServerStatusBadge(true);
        return json;
      } catch (err) {
        console.warn(`[API] Fallback offline untuk aksi: ${action}`, err);
        updateServerStatusBadge(false);
        return null;
      }
    }

    function updateServerStatusBadge(online) {
      isServerOnline = online;
      const badge = document.getElementById('server-status-badge');
      const text = document.getElementById('server-status-text');
      const mobileDot = document.getElementById('mobile-status-dot');
      if (mobileDot) {
        mobileDot.className = online 
          ? 'w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse flex-shrink-0 md:hidden'
          : 'w-2.5 h-2.5 rounded-full bg-amber-500 flex-shrink-0 md:hidden';
        mobileDot.title = online ? 'MySQL Online' : 'Mode Offline';
      }
      if (!badge || !text) return;
      if (online) {
        badge.className = 'hidden md:flex items-center space-x-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200';
        text.innerText = 'MySQL Online';
      } else {
        badge.className = 'hidden md:flex items-center space-x-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-amber-50 text-amber-700 border border-amber-200';
        text.innerText = 'Mode Offline (Lokal)';
      }
    }

    function renderRoleSwitcher(roles) {
      const container = document.getElementById('role-switch-container');
      if (!container) return;
      if (!roles || roles.length <= 1) {
        container.classList.add('hidden');
        return;
      }
      container.classList.remove('hidden');
      container.innerHTML = roles.map(r => {
        const isAct = (r === currentRole);
        const labelFull = r === 'superadmin' ? 'Superadmin' : (r === 'supervisor' ? 'Supervisor' : 'Guru Mandiri');
        const labelShort = r === 'superadmin' ? 'Admin' : (r === 'supervisor' ? 'Spv' : 'Guru');
        const activeClass = isAct ? 'bg-white text-indigo-700 font-bold shadow-sm' : 'text-slate-600 hover:text-slate-900';
        return `<button type="button" onclick="switchRole('${r}')" class="px-2 sm:px-3 py-1 sm:py-1.5 rounded-md text-[11px] sm:text-xs ${activeClass} transition">
          <span class="inline sm:hidden">${labelShort}</span>
          <span class="hidden sm:inline">${labelFull}</span>
        </button>`;
      }).join('');
    }

