    function getGuruEvaluationMetrics(guru) {
      if (!guru) return { rppPct: 0, obsPct: 0, finalScore: 0, predikat: 'Belum Dinilai', badgeColor: 'bg-slate-200 text-slate-700' };

      let rppPct = 0;
      let docScoresFound = false;

      if (guru.mapel === 'BK') {
        let bkSum = 0;
        let bkCount = 0;
        if (guru.bkScores) {
          Object.values(guru.bkScores).forEach(val => {
            bkSum += Number(val) || 0;
            bkCount++;
          });
        }
        if (guru.bkDlScores) {
          Object.values(guru.bkDlScores).forEach(val => {
            bkSum += Number(val) || 0;
            bkCount++;
          });
        }
        if (bkCount > 0) {
          docScoresFound = true;
          rppPct = Math.round((bkSum / 80) * 100);
        }
      } else {
        let rppSum = 0;
        let rppCount = 0;
        if (guru.rppScores) {
          Object.values(guru.rppScores).forEach(val => {
            rppSum += Number(val) || 0;
            rppCount++;
          });
        }
        if (rppCount > 0) {
          docScoresFound = true;
          rppPct = Math.round((rppSum / 90) * 100);
        }
      }

      let obsSum = 0;
      let obsCount = 0;
      if (guru.obsScores) {
        Object.values(guru.obsScores).forEach(val => {
          obsSum += Number(val) || 0;
          obsCount++;
        });
      }

      const maxObsPoints = (guru.mapel === 'BK') ? 108 : 112;
      const obsPct = obsCount > 0 ? Math.round((obsSum / maxObsPoints) * 100) : 0;

      if (!docScoresFound && obsCount === 0) {
        return { rppPct: 0, obsPct: 0, finalScore: 0, predikat: 'Belum Dinilai', badgeColor: 'bg-slate-200 text-slate-700' };
      }

      const finalScore = Math.round((rppPct * 0.3) + (obsPct * 0.7));

      let predikat = 'Perlu Pembinaan (D)';
      let badgeColor = 'bg-rose-100 text-rose-800 border border-rose-300';
      if (finalScore >= 90) {
        predikat = 'Sangat Baik (A)';
        badgeColor = 'bg-emerald-100 text-emerald-800 border border-emerald-300';
      } else if (finalScore >= 80) {
        predikat = 'Baik (B)';
        badgeColor = 'bg-blue-100 text-blue-800 border border-blue-300';
      } else if (finalScore >= 70) {
        predikat = 'Cukup (C)';
        badgeColor = 'bg-amber-100 text-amber-800 border border-amber-300';
      }

      return { rppPct, obsPct, finalScore, predikat, badgeColor };
    }

    function toggleMobileSidebar(open) {
      const sidebar = document.getElementById('app-sidebar');
      const backdrop = document.getElementById('mobile-sidebar-backdrop');
      if (!sidebar) return;
      if (open) {
        sidebar.classList.remove('-translate-x-full');
        if (backdrop) backdrop.classList.remove('hidden');
        document.body.classList.add('overflow-hidden');
      } else {
        sidebar.classList.add('-translate-x-full');
        if (backdrop) backdrop.classList.add('hidden');
        document.body.classList.remove('overflow-hidden');
      }
    }

    function navigateTo(targetView) {
      toggleMobileSidebar(false);
      const views = ['dashboard', 'guru', 'pra', 'observasi', 'coaching', 'laporan', 'pengaturan', 'users'];

      if (currentRole === 'guru' && (targetView === 'guru' || targetView === 'pengaturan' || targetView === 'users')) {
        targetView = 'dashboard';
      }
      if (currentRole === 'supervisor' && (targetView === 'pengaturan' || targetView === 'users')) {
        targetView = 'dashboard';
      }

      try { localStorage.setItem(STORAGE_KEY_VIEW, targetView); } catch(e) {}
      views.forEach(v => {
        const sec = document.getElementById(`view-${v}`);
        const btn = document.getElementById(`nav-${v}`);
        if (sec) {
          if (v === targetView) sec.classList.remove('hidden');
          else sec.classList.add('hidden');
        }
        if (btn) {
          if (v === targetView) {
            btn.className = 'nav-btn w-full flex items-center space-x-3 px-3 py-2.5 rounded-xl font-medium text-xs text-left bg-indigo-600 text-white transition';
          } else {
            const isUserAdminBtn = (v === 'users');
            btn.className = `nav-btn w-full flex items-center space-x-3 px-3 py-2.5 rounded-xl font-medium text-xs text-left ${isUserAdminBtn ? 'text-amber-300' : 'text-slate-300'} hover:bg-slate-800 transition`;
          }
        }
      });
 
      // Tampilkan kartu 'Guru Yang Dinilai' di sidebar HANYA untuk Supervisor & Superadmin pada menu evaluasi guru
      const sideTargetCard = document.getElementById('side-target-guru-card');
      if (sideTargetCard) {
        const evaluationViews = ['pra', 'observasi', 'coaching', 'laporan'];
        if (currentRole !== 'guru' && evaluationViews.includes(targetView)) {
          sideTargetCard.classList.remove('hidden');
        } else {
          sideTargetCard.classList.add('hidden');
        }
      }

      const topTitle = document.getElementById('top-title');
      const activeGuru = guruDatabase.find(g => g.id === selectedGuruId);
      const isBk = activeGuru && activeGuru.mapel === 'BK';

      if (topTitle) {
        const isMobileScreen = window.innerWidth < 640;
        const titlesDesktop = {
          dashboard: currentRole === 'supervisor' ? 'Dashboard Analitik Supervisi (Guru Binaan)' : 'Dashboard Analitik Supervisi',
          guru: currentRole === 'supervisor' ? 'Daftar Guru Binaan & Jadwal Supervisi' : 'Database Guru & Jadwal Penilaian',
          pra: isBk ? 'Pra Observasi-Telaah Modul Ajar (BK)' : 'Pra Observasi-Telaah Modul Ajar (PM)',
          observasi: isBk ? 'Observasi Kelas (BK & Deep Learning)' : 'Observasi Kelas (28 Indikator & Deep Learning)',
          coaching: 'Pasca-Observasi (Coaching Model TIRTA)',
          laporan: 'Rekapitulasi Laporan Supervisi',
          pengaturan: 'Pengaturan Sistem & Supervisor',
          users: 'Manajemen Pengguna (Super Admin)'
        };
        const titlesMobile = {
          dashboard: 'Dashboard',
          guru: currentRole === 'supervisor' ? 'Guru Binaan' : 'Data Guru',
          pra: isBk ? 'Pra (BK)' : 'Pra (PM)',
          observasi: 'Observasi Kelas',
          coaching: 'Coaching TIRTA',
          laporan: 'Laporan Supervisi',
          pengaturan: 'Pengaturan',
          users: 'Manajemen User'
        };
        topTitle.innerText = isMobileScreen 
          ? (titlesMobile[targetView] || 'Dashboard') 
          : (titlesDesktop[targetView] || 'Dashboard Supervisi');
      }

      if (targetView === 'dashboard') {
        updateDashboardKPI();
        renderDashboardTable();
        renderCharts();
      } else if (targetView === 'guru') {
        renderGuruTable();
      } else if (targetView === 'pra') {
        loadPraObservasiData();
      } else if (targetView === 'observasi') {
        loadObservasiData();
      } else if (targetView === 'coaching') {
        loadCoachingData();
      } else if (targetView === 'laporan') {
        updateReportView();
        renderRekapTable();
      } else if (targetView === 'users') {
        renderUserManagement();
      }
    }

    function getCurrentSupervisorId() {
      if (!currentLoggedInUser) return 1;

      // 1. Cek jika user login memiliki active_spv_id langsung dari API
      if (currentLoggedInUser.active_spv_id) {
        return parseInt(currentLoggedInUser.active_spv_id);
      }

      const spvList = (appSettings && Array.isArray(appSettings.supervisors)) ? appSettings.supervisors : [];
      if (spvList.length === 0) return 1;

      // 2. Cocokkan berdasarkan NIP (hanya angka)
      const userNipClean = String(currentLoggedInUser.nip || '').replace(/\D/g, '');
      if (userNipClean) {
        const foundByNip = spvList.find(s => {
          const sNipClean = String(s.nip || '').replace(/\D/g, '');
          return sNipClean && sNipClean === userNipClean;
        });
        if (foundByNip) return parseInt(foundByNip.id);
      }

      // 3. Cocokkan berdasarkan Nama (abaikan gelar & karakter non-alfanumerik)
      const cleanName = (str) => {
        return (str || '')
          .toLowerCase()
          .replace(/(drs\.|dr\.|dra\.|s\.pd\.|m\.pd\.|s\.si\.|s\.p\.|s\.e\.|s\.ag\.|s\.h\.|m\.si\.|gr\.?|\(|\)|supervisor\s*\d*)/gi, '')
          .replace(/[^a-z0-9]/g, ' ')
          .replace(/\s+/g, ' ')
          .trim();
      };

      const userClean = cleanName(currentLoggedInUser.nama);
      if (userClean) {
        const foundByName = spvList.find(s => {
          const sClean = cleanName(s.nama);
          return sClean && (sClean.includes(userClean) || userClean.includes(sClean));
        });
        if (foundByName) return parseInt(foundByName.id);
      }

      return 1;
    }

    function isUserSuperadminOrPengawas() {
      if (currentRole === 'superadmin') return true;
      if (currentRole === 'supervisor' && currentLoggedInUser && currentLoggedInUser.nip === '196808061998021005') {
        return true; // Pengawas sekolah has oversight
      }
      return false;
    }

    function getSupervisorTeachers() {
      if (currentRole === 'guru') {
        return guruDatabase.filter(g => g.id === selectedGuruId);
      }
      if (currentRole === 'superadmin') {
        return guruDatabase;
      }
      // Mode Supervisor
      if (isUserSuperadminOrPengawas()) {
        return guruDatabase;
      }
      const spvId = getCurrentSupervisorId();
      const binaan = guruDatabase.filter(g => g.supervisorId === spvId);
      return binaan.length > 0 ? binaan : guruDatabase;
    }

    function populateTeacherSelects() {
      const teachers = getSupervisorTeachers();
      // Urutkan nama guru secara alfabetis (A-Z) agar memudahkan pencarian cepat
      const sortedTeachers = [...teachers].sort((a, b) => a.nama.localeCompare(b.nama, 'id', { sensitivity: 'base' }));

      ['pra-guru-select', 'obs-guru-select', 'coaching-guru-select', 'laporan-guru-select'].forEach(selId => {
        const el = document.getElementById(selId);
        if (el) {
          el.innerHTML = sortedTeachers.map(g => `<option value="${g.id}">${g.nama} (${g.mapel})</option>`).join('');
          if (sortedTeachers.length > 0) {
            const hasCurrent = sortedTeachers.some(g => g.id === selectedGuruId);
            if (!hasCurrent) {
              selectedGuruId = sortedTeachers[0].id;
            }
            el.value = selectedGuruId;
          }
        }
      });
      syncSelectedGuru(selectedGuruId);
    }

    function switchRole(role) {
      currentRole = role;
      const rolePill = document.getElementById('role-pill');
      const navGuru = document.getElementById('nav-guru');
      const navTextGuru = document.getElementById('nav-text-guru');
      const navPengaturan = document.getElementById('nav-pengaturan');
      const navUsers = document.getElementById('nav-users');
      const roleSwitchContainer = document.getElementById('role-switch-container');
      const dashBtnDb = document.getElementById('dash-btn-db');
      const btnHapusSemua = document.getElementById('btn-hapus-semua-guru');
      const adminGuruActions = document.getElementById('admin-guru-actions');
      const thCheckAll = document.getElementById('th-check-all');
      const bulkBar = document.getElementById('bulk-action-bar');

      deselectAllGuru();

      // Update role switcher buttons highlight
      if (currentLoggedInUser) {
        currentLoggedInUser.active_role = role;
        saveUserSession(currentLoggedInUser);
        if (currentLoggedInUser.available_roles) {
          renderRoleSwitcher(currentLoggedInUser.available_roles);
        }
      }

      // Update sidebar user login profile info
      const sideUserNama = document.getElementById('side-user-nama');
      const sideUserRole = document.getElementById('side-user-role');
      const sideUserIcon = document.getElementById('side-user-icon');
      if (sideUserNama && sideUserRole) {
        if (role === 'superadmin') {
          sideUserNama.innerText = (currentLoggedInUser && currentLoggedInUser.nama) ? currentLoggedInUser.nama : 'Superadmin Utama';
          sideUserRole.innerText = 'Super Admin (Full Access)';
          if (sideUserIcon) sideUserIcon.className = 'fa-solid fa-user-shield';
        } else if (role === 'supervisor') {
          const spv = appSettings.supervisors.find(s => s.id === getCurrentSupervisorId());
          const spvName = (currentLoggedInUser && currentLoggedInUser.nama) ? currentLoggedInUser.nama : (spv ? spv.nama : 'Supervisor Penilai');
          sideUserNama.innerText = spvName.split('(')[0].trim();
          sideUserRole.innerText = 'Supervisor Penilai';
          if (sideUserIcon) sideUserIcon.className = 'fa-solid fa-user-tie';
        } else {
          sideUserNama.innerText = (currentLoggedInUser && currentLoggedInUser.nama) ? currentLoggedInUser.nama : 'Guru';
          sideUserRole.innerText = 'Guru (Self-Asesmen)';
          if (sideUserIcon) sideUserIcon.className = 'fa-solid fa-chalkboard-user';
        }
      }

      if (role === 'guru') {
        if (rolePill) {
          rolePill.innerText = 'Mode Guru (Self-Asesmen)';
          rolePill.className = 'hidden md:inline-block px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200';
        }
        if (navGuru) {
          navGuru.classList.add('hidden');
          navGuru.style.display = 'none';
        }
        if (navPengaturan) {
          navPengaturan.classList.add('hidden');
          navPengaturan.style.display = 'none';
        }
        if (navUsers) {
          navUsers.classList.add('hidden');
          navUsers.style.display = 'none';
        }
        if (dashBtnDb) dashBtnDb.classList.add('hidden');
        if (adminGuruActions) adminGuruActions.classList.add('hidden');
        if (btnHapusSemua) btnHapusSemua.classList.add('hidden');
        if (thCheckAll) thCheckAll.classList.add('hidden');
        if (bulkBar) bulkBar.classList.add('hidden');

        // Jika multi-role, roleSwitchContainer tetap tampil agar bisa switch kembali
        if (roleSwitchContainer) {
          const hasMultipleRoles = currentLoggedInUser && currentLoggedInUser.available_roles && currentLoggedInUser.available_roles.length > 1;
          if (hasMultipleRoles) roleSwitchContainer.classList.remove('hidden');
          else roleSwitchContainer.classList.add('hidden');
        }

        if (currentLoggedInUser && currentLoggedInUser.id) {
          syncSelectedGuru(currentLoggedInUser.id);
        }

        const curActive = document.querySelector('section:not(.hidden)');
        if (curActive && (curActive.id === 'view-guru' || curActive.id === 'view-pengaturan' || curActive.id === 'view-users')) {
          navigateTo('dashboard');
        }
      } else if (role === 'superadmin') {
        if (rolePill) {
          rolePill.innerText = 'Mode Superadmin (Full Access)';
          rolePill.className = 'hidden md:inline-block px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-rose-50 text-rose-700 border border-rose-300 shadow-sm';
        }
        if (navGuru) {
          navGuru.classList.remove('hidden');
          navGuru.style.display = 'flex';
        }
        if (navTextGuru) {
          navTextGuru.innerText = `Database Guru (${guruDatabase.length} Guru)`;
        }
        if (navPengaturan) {
          navPengaturan.classList.remove('hidden');
          navPengaturan.style.display = 'flex';
        }
        if (navUsers) {
          navUsers.classList.remove('hidden');
          navUsers.style.display = 'flex';
        }
        if (dashBtnDb) dashBtnDb.classList.remove('hidden');
        if (adminGuruActions) adminGuruActions.classList.remove('hidden');
        if (btnHapusSemua) btnHapusSemua.classList.remove('hidden');
        if (thCheckAll) thCheckAll.classList.remove('hidden');
        if (roleSwitchContainer) roleSwitchContainer.classList.remove('hidden');
      } else {
        // Mode Supervisor
        const binaanCount = getSupervisorTeachers().length;
        if (rolePill) {
          const isPengawas = currentLoggedInUser && currentLoggedInUser.nip === '196808061998021005';
          if (isPengawas) {
            rolePill.innerText = 'Mode Pengawas Sekolah (Mochamad Solikin)';
            rolePill.className = 'hidden md:inline-block px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-purple-50 text-purple-700 border border-purple-300 shadow-sm';
          } else {
            const spv = appSettings.supervisors.find(s => s.id === getCurrentSupervisorId());
            const spvLabel = spv ? spv.nama.split('(')[0].trim() : 'Supervisor';
            rolePill.innerText = `Mode Supervisor (${spvLabel})`;
            rolePill.className = 'hidden md:inline-block px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-indigo-50 text-indigo-700 border border-indigo-200';
          }
        }
        if (navGuru) {
          navGuru.classList.remove('hidden');
          navGuru.style.display = 'flex';
        }
        if (navTextGuru) {
          navTextGuru.innerText = `Data Guru Binaan (${binaanCount} Guru)`;
        }
        // Strict hiding of admin menus in supervisor mode
        if (navPengaturan) {
          navPengaturan.classList.add('hidden');
          navPengaturan.style.display = 'none';
        }
        if (navUsers) {
          navUsers.classList.add('hidden');
          navUsers.style.display = 'none';
        }
        if (dashBtnDb) dashBtnDb.classList.add('hidden');
        if (adminGuruActions) adminGuruActions.classList.add('hidden');
        if (btnHapusSemua) btnHapusSemua.classList.add('hidden');
        if (thCheckAll) thCheckAll.classList.add('hidden');
        if (bulkBar) bulkBar.classList.add('hidden');
        if (roleSwitchContainer) roleSwitchContainer.classList.remove('hidden');

        // Redirect away if currently on admin-only page
        const curActive = document.querySelector('section:not(.hidden)');
        if (curActive && (curActive.id === 'view-pengaturan' || curActive.id === 'view-users')) {
          navigateTo('dashboard');
        }
      }

      populateTeacherSelects();
      updateTeacherPickerVisibility();
      const btnCetakRekap = document.getElementById('btn-cetak-rekap-keseluruhan');
      if (btnCetakRekap) {
        if (role === 'guru') btnCetakRekap.classList.add('hidden');
        else btnCetakRekap.classList.remove('hidden');
      }
      updateDashboardKPI();
      renderDashboardTable();
      renderGuruTable();
      renderCharts();
      renderRekapTable();
      showToast(`Mode aktif: ${role.toUpperCase()}`);

      // Sync role switch with backend API in background
      apiCall('switch_role', { role }).catch(() => {});
    }

    function updateTeacherPickerVisibility() {
      const isGuru = (currentRole === 'guru');
      const activeGuru = guruDatabase.find(g => g.id === selectedGuruId) || guruDatabase[0];
      const guruLabel = activeGuru ? `${activeGuru.nama} (${activeGuru.mapel})` : '-';

      const praPicker = document.getElementById('pra-guru-picker-container');
      const praBadge = document.getElementById('pra-guru-badge-container');
      const praBadgeText = document.getElementById('pra-guru-badge-text');
      if (praPicker && praBadge) {
        if (isGuru) {
          praPicker.classList.add('hidden');
          praBadge.classList.remove('hidden');
          praBadge.classList.add('flex');
          if (praBadgeText) praBadgeText.innerText = `Guru: ${guruLabel}`;
        } else {
          praPicker.classList.remove('hidden');
          praBadge.classList.add('hidden');
          praBadge.classList.remove('flex');
        }
      }

      const obsPicker = document.getElementById('obs-guru-picker-container');
      const obsBadge = document.getElementById('obs-guru-badge-container');
      const obsBadgeText = document.getElementById('obs-guru-badge-text');
      if (obsPicker && obsBadge) {
        if (isGuru) {
          obsPicker.classList.add('hidden');
          obsBadge.classList.remove('hidden');
          obsBadge.classList.add('flex');
          if (obsBadgeText) obsBadgeText.innerText = `Guru: ${guruLabel}`;
        } else {
          obsPicker.classList.remove('hidden');
          obsBadge.classList.add('hidden');
          obsBadge.classList.remove('flex');
        }
      }

      const coachingPicker = document.getElementById('coaching-guru-picker-container');
      const coachingBadge = document.getElementById('coaching-guru-badge-container');
      const coachingBadgeText = document.getElementById('coaching-guru-badge-text');
      if (coachingPicker && coachingBadge) {
        if (isGuru) {
          coachingPicker.classList.add('hidden');
          coachingBadge.classList.remove('hidden');
          coachingBadge.classList.add('flex');
          if (coachingBadgeText) coachingBadgeText.innerText = `Guru: ${guruLabel}`;
        } else {
          coachingPicker.classList.remove('hidden');
          coachingBadge.classList.add('hidden');
          coachingBadge.classList.remove('flex');
        }
      }

      const lapPicker = document.getElementById('laporan-guru-picker-container');
      const lapBadge = document.getElementById('laporan-guru-badge-container');
      const lapBadgeText = document.getElementById('laporan-guru-badge-text');
      if (lapPicker && lapBadge) {
        if (isGuru) {
          lapPicker.classList.add('hidden');
          lapBadge.classList.remove('hidden');
          lapBadge.classList.add('flex');
          if (lapBadgeText) lapBadgeText.innerText = `Laporan Mandiri: ${guruLabel}`;
        } else {
          lapPicker.classList.remove('hidden');
          lapBadge.classList.add('hidden');
          lapBadge.classList.remove('flex');
        }
      }

      const sideTargetCard = document.getElementById('side-target-guru-card');
      if (sideTargetCard) {
        const curActive = document.querySelector('section:not(.hidden)');
        const activeViewId = curActive ? curActive.id.replace('view-', '') : '';
        const evaluationViews = ['pra', 'observasi', 'coaching', 'laporan'];
        if (!isGuru && evaluationViews.includes(activeViewId)) {
          sideTargetCard.classList.remove('hidden');
        } else {
          sideTargetCard.classList.add('hidden');
        }
