    function updateSidebarPredikat(guru) {
      if (!guru) return;
      const sidePred = document.getElementById('side-predikat');
      if (sidePred) {
        const metrics = getGuruEvaluationMetrics(guru);
        sidePred.innerText = metrics.predikat;
        sidePred.className = `px-2 py-0.5 rounded text-[10px] font-bold ${metrics.badgeColor}`;
      }
    }

    function checkFieldValidation(inputEl, warnBadgeEl) {
      if (!inputEl) return true;
      const isFilled = inputEl.value && inputEl.value.trim().length > 0;
      if (isFilled) {
        inputEl.classList.remove('border-rose-400', 'bg-rose-50/30');
        if (warnBadgeEl) {
          warnBadgeEl.classList.add('hidden');
          warnBadgeEl.classList.remove('inline-flex');
        }
      } else {
        inputEl.classList.add('border-rose-400', 'bg-rose-50/30');
        if (warnBadgeEl) {
          warnBadgeEl.classList.remove('hidden');
          warnBadgeEl.classList.add('inline-flex');
        }
      }
      return isFilled;
    }

    function autoSavePraInput() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (guru.mapel === 'BK') {
        const bkBidang = document.getElementById('pra-bk-bidang')?.value.trim() || '';
        const bkFokus = document.getElementById('pra-bk-fokus')?.value.trim() || '';
        const bkTujuan = document.getElementById('pra-bk-tujuan')?.value.trim() || '';
        guru.bkBidangLayanan = bkBidang;
        guru.bkFokusLayanan = bkFokus;
        guru.bkTujuanLayanan = bkTujuan;
        guru.materiTopik = bkFokus ? (bkBidang ? `${bkBidang}: ${bkFokus}` : bkFokus) : bkBidang;
        guru.tujuanPembelajaran = bkTujuan;
        if (!guru.praFeedback) guru.praFeedback = {};
        guru.praFeedback.bkBidangLayanan = bkBidang;
        guru.praFeedback.bkFokusLayanan = bkFokus;
        guru.praFeedback.bkTujuanLayanan = bkTujuan;
        checkFieldValidation(document.getElementById('pra-bk-bidang'), document.getElementById('pra-warn-bk-bidang'));
        checkFieldValidation(document.getElementById('pra-bk-fokus'), document.getElementById('pra-warn-bk-fokus'));
        checkFieldValidation(document.getElementById('pra-bk-tujuan'), document.getElementById('pra-warn-bk-tujuan'));
      } else {
        guru.materiTopik = document.getElementById('pra-input-materi')?.value || '';
        guru.tujuanPembelajaran = document.getElementById('pra-input-tujuan')?.value || '';
        checkFieldValidation(document.getElementById('pra-input-materi'), document.getElementById('pra-warn-materi'));
        checkFieldValidation(document.getElementById('pra-input-tujuan'), document.getElementById('pra-warn-tujuan'));
      }
      guru.tanggalTelaah = document.getElementById('pra-input-tanggal')?.value || '';
      guru.targetPerilaku = document.getElementById('pra-input-target-perilaku')?.value || '';

      if (!guru.praFeedback) guru.praFeedback = {};
      guru.praFeedback.kekuatan = document.getElementById('pra-fb-kekuatan')?.value || '';
      guru.praFeedback.prioritas = document.getElementById('pra-fb-prioritas')?.value || '';
      guru.praFeedback.refleksi = document.getElementById('pra-fb-refleksi')?.value || '';
      guru.praFeedback.kesepakatan = document.getElementById('pra-fb-kesepakatan')?.value || '';
      guru.praFeedback.waktuBerikutnya = document.getElementById('pra-fb-waktu')?.value || '';

      saveDataToLocalStorage();
    }

    function autoSaveObsInput() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      guru.catatanFakta = document.getElementById('obs-catatan-fakta')?.value || '';
      guru.tanggalObservasi = document.getElementById('obs-input-tanggal')?.value || '';
      guru.targetPerilaku = document.getElementById('obs-input-target-perilaku')?.value || '';
      checkFieldValidation(document.getElementById('obs-catatan-fakta'), document.getElementById('obs-warn-catatan-fakta'));
      saveDataToLocalStorage();
    }

    function autoSaveCoachingInput() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.coaching) guru.coaching = {};
      guru.coaching.tujuan = document.getElementById('coach-tujuan')?.value || '';
      guru.coaching.identifikasi = document.getElementById('coach-identifikasi')?.value || '';
      guru.coaching.rencana = document.getElementById('coach-rencana')?.value || '';
      guru.coaching.tanggungJawab = document.getElementById('coach-tanggungjawab')?.value || '';
      checkFieldValidation(document.getElementById('coach-tujuan'), document.getElementById('coach-warn-tujuan'));
      checkFieldValidation(document.getElementById('coach-identifikasi'), document.getElementById('coach-warn-identifikasi'));
      checkFieldValidation(document.getElementById('coach-rencana'), document.getElementById('coach-warn-rencana'));
      checkFieldValidation(document.getElementById('coach-tanggungjawab'), document.getElementById('coach-warn-tanggungjawab'));
      saveDataToLocalStorage();
    }

    function syncSelectedGuru(id, forceReload = false) {
      const targetId = parseInt(id) || 1;
      const isTeacherChanged = (selectedGuruId !== targetId);
      selectedGuruId = targetId;
      try { localStorage.setItem(STORAGE_KEY_SELECTED_GURU, String(selectedGuruId)); } catch(e) {}
      const guru = guruDatabase.find(g => g.id === selectedGuruId) || guruDatabase[0];
      if (!guru) return;

      const sideNama = document.getElementById('side-nama');
      const sideMapel = document.getElementById('side-mapel');
      const sidePred = document.getElementById('side-predikat');

      if (sideNama) sideNama.innerText = guru.nama;
      if (sideMapel) sideMapel.innerText = `${guru.mapel} • ${guru.kelas}`;

      updateSidebarPredikat(guru);

      ['pra-guru-select', 'obs-guru-select', 'coaching-guru-select', 'laporan-guru-select'].forEach(selId => {
        const el = document.getElementById(selId);
        if (el && el.value != guru.id) el.value = guru.id;
      });

      const obsNamaBanner = document.getElementById('obs-guru-nama-banner');
      const obsMetaBanner = document.getElementById('obs-guru-meta-banner');
      const obsTargetBadge = document.getElementById('obs-target-badge');

      if (obsNamaBanner) obsNamaBanner.innerText = guru.nama;
      if (obsMetaBanner) obsMetaBanner.innerText = `${guru.mapel} • ${guru.kelas} • NIP: ${guru.nip}`;
      const targetPerilakuVal = guru.targetPerilaku || 'Instruksi Pembelajaran';
      if (obsTargetBadge) obsTargetBadge.innerText = `Fokus: ${targetPerilakuVal}`;
      const obsFokusPmmText = document.getElementById('obs-fokus-pmm-text');
      if (obsFokusPmmText) obsFokusPmmText.innerText = targetPerilakuVal;

      const navPra = document.getElementById('nav-text-pra');
      const navObs = document.getElementById('nav-text-obs');
      if (guru.mapel === 'BK') {
        if (navPra) navPra.innerText = 'Pra Observasi-Telaah Modul Ajar (BK)';
        if (navObs) navObs.innerText = 'Observasi Layanan (27 Ind.)';
      } else {
        if (navPra) navPra.innerText = 'Pra Observasi-Telaah Modul Ajar (PM)';
        if (navObs) navObs.innerText = 'Observasi Kelas (28 Ind.)';
      }

      updateTeacherPickerVisibility();

      // Hanya reload isi form jika guru yang dipilih benar-benar berganti ATAU dipaksa (forceReload)
      if (isTeacherChanged || forceReload) {
        const curSection = document.querySelector('section[id^="view-"]:not(.hidden)') || document.querySelector('section:not(.hidden)');
        if (curSection) {
          if (curSection.id === 'view-pra') loadPraObservasiData();
          else if (curSection.id === 'view-observasi') loadObservasiData();
          else if (curSection.id === 'view-coaching') loadCoachingData();
          else if (curSection.id === 'view-laporan') updateReportView();
        }
      }
    }

    function loadPraObservasiData() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;

      const idSekolah = document.getElementById('pra-id-sekolah');
      const idNamaMapel = document.getElementById('pra-id-nama-mapel');
      const idFaseKelas = document.getElementById('pra-id-fase-kelas');
      const idPeriode = document.getElementById('pra-id-periode');
      const inMateri = document.getElementById('pra-input-materi');
      const inTujuan = document.getElementById('pra-input-tujuan');
      const inTanggal = document.getElementById('pra-input-tanggal');
      const inTarget = document.getElementById('pra-input-target-perilaku');

      if (idSekolah) idSekolah.value = appSettings.sekolah;
      if (idNamaMapel) idNamaMapel.value = `${guru.nama} / ${guru.mapel}`;
      if (idFaseKelas) idFaseKelas.value = `Fase D (${guru.kelas})`;
      if (idPeriode) idPeriode.value = appSettings.periode;
      if (inTanggal) inTanggal.value = guru.tanggalTelaah || new Date().toISOString().slice(0, 10);
      if (inTarget) inTarget.value = guru.targetPerilaku || 'Instruksi Pembelajaran';

      // Dynamic Display BK vs Guru Mapel
      const fieldsMapel = document.getElementById('pra-fields-mapel');
      const fieldsBk = document.getElementById('pra-fields-bk');
      const inBkBidang = document.getElementById('pra-bk-bidang');
      const inBkFokus = document.getElementById('pra-bk-fokus');
      const inBkTujuan = document.getElementById('pra-bk-tujuan');

      if (guru.mapel === 'BK') {
        if (fieldsMapel) fieldsMapel.classList.add('hidden');
        if (fieldsBk) fieldsBk.classList.remove('hidden');
        if (inBkBidang) inBkBidang.value = guru.bkBidangLayanan || (guru.praFeedback && guru.praFeedback.bkBidangLayanan) || '';
        if (inBkFokus) inBkFokus.value = guru.bkFokusLayanan || (guru.praFeedback && guru.praFeedback.bkFokusLayanan) || guru.materiTopik || '';
        if (inBkTujuan) inBkTujuan.value = guru.bkTujuanLayanan || (guru.praFeedback && guru.praFeedback.bkTujuanLayanan) || guru.tujuanPembelajaran || '';
        checkFieldValidation(inBkBidang, document.getElementById('pra-warn-bk-bidang'));
        checkFieldValidation(inBkFokus, document.getElementById('pra-warn-bk-fokus'));
        checkFieldValidation(inBkTujuan, document.getElementById('pra-warn-bk-tujuan'));
      } else {
        if (fieldsMapel) fieldsMapel.classList.remove('hidden');
        if (fieldsBk) fieldsBk.classList.add('hidden');
        if (inMateri) inMateri.value = guru.materiTopik || '';
        if (inTujuan) inTujuan.value = guru.tujuanPembelajaran || '';
        checkFieldValidation(inMateri, document.getElementById('pra-warn-materi'));
        checkFieldValidation(inTujuan, document.getElementById('pra-warn-tujuan'));
      }

      const praSpvSel = document.getElementById('pra-supervisor-select');
      if (praSpvSel) {
        praSpvSel.innerHTML = appSettings.supervisors.map(s => `
          <option value="${s.id}" ${guru.supervisorId === s.id ? 'selected' : ''}>${s.nama}</option>
        `).join('');
      }

      const titleEl = document.getElementById('pra-rubrik-title-text');
      const rppContainer = document.getElementById('pra-rpp-rubrik-container');
      const bkContainer = document.getElementById('pra-bk-rubrik-container');
      const praSecTitle = document.getElementById('pra-section-title');
      const praSecDesc = document.getElementById('pra-section-desc');
      const petunjukReguler = document.getElementById('pra-petunjuk-skala-reguler');

      if (!guru.praFeedback) guru.praFeedback = {};
      const fbKekuatan = document.getElementById('pra-fb-kekuatan');
      const fbPrioritas = document.getElementById('pra-fb-prioritas');
      const fbRefleksi = document.getElementById('pra-fb-refleksi');
      const fbKesepakatan = document.getElementById('pra-fb-kesepakatan');
      const fbWaktu = document.getElementById('pra-fb-waktu');

      if (fbKekuatan) fbKekuatan.value = guru.praFeedback.kekuatan || '';
      if (fbPrioritas) fbPrioritas.value = guru.praFeedback.prioritas || '';
      if (fbRefleksi) fbRefleksi.value = guru.praFeedback.refleksi || '';
      if (fbKesepakatan) fbKesepakatan.value = guru.praFeedback.kesepakatan || '';
      if (fbWaktu) fbWaktu.value = guru.praFeedback.waktuBerikutnya || '';

      if (guru.mapel === 'BK') {
        if (praSecTitle) praSecTitle.innerText = 'Pra Observasi-Telaah Modul Ajar (BK)';
        if (praSecDesc) praSecDesc.innerText = 'Penetapan target perilaku kinerja dan telaah dokumen perencanaan pelayanan (Modul Pelayanan BK).';
        if (titleEl) titleEl.innerText = 'Telaah Dokumen Perencanaan Pelayanan (Modul Pelayanan BK - 14 Aspek & Deep Learning)';
        if (petunjukReguler) petunjukReguler.classList.add('hidden');
        if (rppContainer) rppContainer.classList.add('hidden');
        if (bkContainer) bkContainer.classList.remove('hidden');
        renderPraBkRubrik(guru);
      } else {
        if (praSecTitle) praSecTitle.innerText = 'Pra Observasi-Telaah Modul Ajar (PM)';
        if (praSecDesc) praSecDesc.innerText = 'Instrumen supervisi akademik berbasis Pembelajaran Mendalam (Deep Learning Revisi 2025).';
        if (titleEl) titleEl.innerText = 'Instrumen Inti Telaah (30 Indikator dalam Enam Dimensi PM)';
        if (petunjukReguler) petunjukReguler.classList.remove('hidden');
        if (rppContainer) rppContainer.classList.remove('hidden');
        if (bkContainer) bkContainer.classList.add('hidden');
        renderPraRpp30Indikator(guru);
      }

      syncAllSignatures(guru);
    }

    function renderPraRpp30Indikator(guru) {
      const container = document.getElementById('pra-rpp-rubrik-container');
      if (!container) return;
      container.innerHTML = '';

      if (!guru.rppScores) guru.rppScores = {};

      DIMENSI_RPP_PM.forEach(dim => {
        const dimCard = document.createElement('div');
        dimCard.className = 'bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-3';

        let subtotal = 0;
        dim.indikator.forEach(ind => {
          subtotal += Number(guru.rppScores[ind.id]) || 0;
        });

        let indRows = dim.indikator.map(ind => {
          const isSet = (guru.rppScores && guru.rppScores[ind.id] !== undefined);
          const score = isSet ? Number(guru.rppScores[ind.id]) : null;
          const isUnfilled = !isSet;
          return `
            <div id="rpp-row-${ind.id}" class="${isUnfilled ? 'bg-rose-50/60 border-rose-300' : 'bg-slate-50/70 border-slate-200'} p-3 rounded-lg border flex flex-col md:flex-row md:items-center justify-between gap-2.5 text-xs transition-colors">
              <div class="flex-1 pr-2 flex items-center space-x-2">
                <span class="font-bold text-slate-800">${ind.id}.</span>
                <span class="text-slate-700 ml-1 font-medium">${ind.text}</span>
                <span id="rpp-warn-${ind.id}" class="${isUnfilled ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print flex-shrink-0">
                  <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                  <span>Belum Diisi</span>
                </span>
              </div>
              <div class="flex items-center space-x-2 flex-shrink-0">
                <span id="rpp-print-${ind.id}" class="print-score-badge">${isSet ? 'Skor: ' + score : 'Skor: -'}</span>
                <div class="flex items-center space-x-1" id="rpp-group-${ind.id}">
                  ${[0, 1, 2, 3].map(s => `
                    <button type="button" onclick="setRppScore(${ind.id}, ${s})" title="Skor ${s}" class="rpp-btn-${ind.id} px-2.5 py-1 rounded text-xs font-bold transition ${isSet && score === s ? 'bg-indigo-600 text-white shadow-sm' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-100'}">
                      ${s}
                    </button>
                  `).join('')}
                </div>
              </div>
            </div>
          `;
        }).join('');

        let noteBox = '';
        if (dim.pertanyaanPenelaah) {
          noteBox = `
            <div class="p-2.5 bg-amber-50/70 rounded-lg border border-amber-200 text-[11px] text-amber-900 flex items-start space-x-2">
              <i class="fa-solid fa-circle-question text-amber-600 mt-0.5"></i>
              <div>
                <strong>Pertanyaan penelaah:</strong> ${dim.pertanyaanPenelaah}
              </div>
            </div>
          `;
        } else if (dim.catatanAhli) {
          noteBox = `
            <div class="p-2.5 bg-blue-50/70 rounded-lg border border-blue-200 text-[11px] text-blue-900 flex items-start space-x-2">
              <i class="fa-solid fa-graduation-cap text-blue-600 mt-0.5"></i>
              <div>
                <strong>Catatan ahli:</strong> ${dim.catatanAhli}
              </div>
            </div>
          `;
        }

        dimCard.innerHTML = `
          <div class="flex flex-col md:flex-row md:items-center justify-between gap-1 border-b border-slate-200 pb-2.5">
            <div>
              <h5 class="font-bold text-xs text-indigo-950 flex items-center space-x-2">
                <span class="w-6 h-6 rounded-lg bg-indigo-600 text-white flex items-center justify-center text-xs font-bold shadow-sm">${dim.dimensi}</span>
                <span>${dim.nama}</span>
              </h5>
              <p class="text-[11px] text-slate-500 italic mt-0.5 ml-8">Fokus: ${dim.fokus}</p>
            </div>
            <div class="flex items-center space-x-2 self-end md:self-auto">
              <span class="text-[11px] text-slate-400">Subtotal:</span>
              <span id="subtotal-dimensi-${dim.dimensi}" class="text-xs font-bold text-indigo-700 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-200">${subtotal} / ${dim.maxSkor}</span>
            </div>
          </div>
          <div class="space-y-2 pt-1">${indRows}</div>
          ${noteBox}
        `;
        container.appendChild(dimCard);
      });

      calculateRppScoreLive();
    }

    function setRppScore(indId, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.rppScores) guru.rppScores = {};
      guru.rppScores[indId] = score;

      document.querySelectorAll(`.rpp-btn-${indId}`).forEach(b => {
        b.className = `rpp-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-white border border-slate-200 text-slate-600 hover:bg-slate-100`;
      });
      if (window.event && window.event.target) {
        window.event.target.className = `rpp-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-indigo-600 text-white shadow-sm`;
      }

      // Clear warning and update print badge
      const rppRow = document.getElementById(`rpp-row-${indId}`);
      if (rppRow) {
        rppRow.className = 'bg-slate-50/70 p-3 rounded-lg border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-2.5 text-xs transition-colors';
      }
      const rppWarn = document.getElementById(`rpp-warn-${indId}`);
      if (rppWarn) {
        rppWarn.className = 'hidden';
      }
      const rppPrint = document.getElementById(`rpp-print-${indId}`);
      if (rppPrint) {
        rppPrint.innerText = `Skor: ${score}`;
      }

      const dim = DIMENSI_RPP_PM.find(d => d.indikator.some(i => i.id === indId));
      if (dim) {
        let sub = 0;
        dim.indikator.forEach(i => sub += Number(guru.rppScores[i.id]) || 0);
        const subEl = document.getElementById(`subtotal-dimensi-${dim.dimensi}`);
        if (subEl) subEl.innerText = `${sub} / ${dim.maxSkor}`;
      }

      calculateRppScoreLive();
      updateSidebarPredikat(guru);
      saveDataToLocalStorage();
    }

    function calculateRppScoreLive() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      const metrics = getGuruEvaluationMetrics(guru);

      const livePct = document.getElementById('pra-live-rpp-pct');
      const liveBadge = document.getElementById('pra-live-rpp-badge');
      const liveLabel = document.getElementById('pra-live-rpp-label');

      if (liveLabel) liveLabel.innerText = (guru.mapel === 'BK') ? 'Skor Pelayanan BK:' : 'Skor Telaah Dokumen (30 Ind):';
      if (livePct) livePct.innerText = `${metrics.rppPct}%`;
      if (liveBadge) {
        liveBadge.innerText = metrics.predikat;
        liveBadge.className = `font-bold text-[10px] px-2 py-0.5 rounded ${metrics.badgeColor}`;
      }
    }

    function renderPraBkRubrik(guru) {
      if (!guru) return;
      if (!guru.bkScores) guru.bkScores = {};
      if (!guru.bkDlScores) guru.bkDlScores = {};
      if (!guru.bkDlNotes) guru.bkDlNotes = {};

      const list14 = document.getElementById('pra-bk-14-items-list');
      if (list14) {
        list14.innerHTML = '';
        ASPEK_BK_TELAAH.forEach(item => {
          const isSet = (guru.bkScores && guru.bkScores[item.id] !== undefined);
          const score = isSet ? Number(guru.bkScores[item.id]) : 0;
          const isUnfilled = !isSet;
          const row = document.createElement('div');
          row.id = `bk-telaah-row-${item.id}`;
          row.className = `${isUnfilled ? 'bg-rose-50/60 border-rose-300' : 'bg-white border-slate-200'} p-3 rounded-xl border flex flex-col md:flex-row md:items-center justify-between gap-2.5 text-xs transition-colors`;
          row.innerHTML = `
            <div class="flex-1 pr-2 flex items-center space-x-2">
              <span class="font-bold text-slate-800 text-xs">${item.id}.</span>
              <span class="text-slate-700 ml-1 font-medium">${item.text}</span>
              <span id="bk-telaah-warn-${item.id}" class="${isUnfilled ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print flex-shrink-0">
                <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                <span>Belum Diisi</span>
              </span>
            </div>
            <div class="flex items-center space-x-2 flex-shrink-0">
              <span id="bk-telaah-print-${item.id}" class="print-score-badge">${isSet ? 'Skor: ' + score : 'Skor: -'}</span>
              <div class="flex items-center space-x-1" id="bk-score-group-${item.id}">
                ${[0, 1, 2, 3, 4].map(s => `
                  <button type="button" onclick="setBkScore(${item.id}, ${s})" class="bk-score-btn-${item.id} px-2.5 py-1 rounded text-xs font-bold transition ${isSet && score === s ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                    ${s}
                  </button>
                `).join('')}
              </div>
            </div>
          `;
          list14.appendChild(row);
        });
      }

      const prinsipList = document.getElementById('pra-bk-prinsip-list');
      if (prinsipList) {
        prinsipList.innerHTML = '';
        PRINSIP_BK_DL.forEach(p => {
          const isSet = (guru.bkDlScores && guru.bkDlScores[p.key] !== undefined);
          const score = isSet ? Number(guru.bkDlScores[p.key]) : 0;
          const note = (guru.bkDlNotes && guru.bkDlNotes[p.key]) ? guru.bkDlNotes[p.key] : '';
          const card = document.createElement('div');
          card.id = `bk-prinsip-card-${p.key}`;
          card.className = `${!isSet ? 'bg-rose-50/60 border-rose-300' : 'bg-white border-slate-200'} p-3.5 rounded-xl border space-y-2.5 text-xs transition-colors`;
          card.innerHTML = `
            <div class="flex flex-col md:flex-row md:items-center justify-between gap-2">
              <div class="flex items-center space-x-2">
                <span class="font-bold text-indigo-900 text-xs uppercase tracking-wide">Prinsip: ${p.title}</span>
                <span id="bk-prinsip-warn-${p.key}" class="${!isSet ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print">
                  <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                  <span>Belum Diisi</span>
                </span>
                <p class="text-[11px] text-slate-600 font-medium mt-0.5"><i class="fa-regular fa-circle-question text-indigo-500 mr-1"></i>${p.pemantik}</p>
              </div>
              <div class="flex items-center space-x-2 flex-shrink-0">
                <span id="bk-prinsip-print-${p.key}" class="print-score-badge">${isSet ? 'Skor: ' + score : 'Skor: -'}</span>
                <div class="flex items-center space-x-1" id="bk-dl-group-${p.key}">
                  <span class="text-[11px] text-slate-400 mr-1 no-print">Skala (0-4):</span>
                  ${[0, 1, 2, 3, 4].map(s => `
                    <button type="button" onclick="setBkDlScore('${p.key}', ${s})" class="bk-dl-btn-${p.key} px-2.5 py-1 rounded text-xs font-bold transition ${isSet && score === s ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                      ${s}
                    </button>
                  `).join('')}
                </div>
              </div>
            </div>
            <div>
              <label class="block text-[11px] font-semibold text-slate-600 mb-1">Rencana dalam modul:</label>
              <textarea rows="2" oninput="saveBkDlNote('${p.key}', this.value)" placeholder="Tuliskan wujud konkret prinsip ${p.title} dalam modul layanan..." class="w-full text-xs p-2 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-500">${note}</textarea>
            </div>
          `;
          prinsipList.appendChild(card);
        });
      }

      const siklusList = document.getElementById('pra-bk-siklus-list');
      if (siklusList) {
        siklusList.innerHTML = '';
        SIKLUS_BK_DL.forEach(s => {
          const isSet = (guru.bkDlScores && guru.bkDlScores[s.key] !== undefined);
          const score = isSet ? Number(guru.bkDlScores[s.key]) : 0;
          const note = (guru.bkDlNotes && guru.bkDlNotes[s.key]) ? guru.bkDlNotes[s.key] : '';
          const card = document.createElement('div');
          card.id = `bk-siklus-card-${s.key}`;
          card.className = `${!isSet ? 'bg-rose-50/60 border-rose-300' : 'bg-white border-slate-200'} p-3.5 rounded-xl border space-y-2.5 text-xs transition-colors`;
          card.innerHTML = `
            <div class="flex flex-col md:flex-row md:items-center justify-between gap-2">
              <div class="flex items-center space-x-2">
                <span class="font-bold text-indigo-900 text-xs uppercase tracking-wide">Siklus: ${s.title}</span>
                <span id="bk-siklus-warn-${s.key}" class="${!isSet ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print">
                  <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                  <span>Belum Diisi</span>
                </span>
                <p class="text-[11px] text-slate-600 font-medium mt-0.5"><i class="fa-solid fa-arrows-spin text-indigo-500 mr-1"></i>${s.pemantik}</p>
              </div>
              <div class="flex items-center space-x-2 flex-shrink-0">
                <span id="bk-siklus-print-${s.key}" class="print-score-badge">${isSet ? 'Skor: ' + score : 'Skor: -'}</span>
                <div class="flex items-center space-x-1" id="bk-dl-group-${s.key}">
                  <span class="text-[11px] text-slate-400 mr-1 no-print">Skala (0-4):</span>
                  ${[0, 1, 2, 3, 4].map(val => `
                    <button type="button" onclick="setBkDlScore('${s.key}', ${val})" class="bk-dl-btn-${s.key} px-2.5 py-1 rounded text-xs font-bold transition ${isSet && score === val ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                      ${val}
                    </button>
                  `).join('')}
                </div>
              </div>
            </div>
            <div>
              <label class="block text-[11px] font-semibold text-slate-600 mb-1">Rencana dalam modul:</label>
              <textarea rows="2" oninput="saveBkDlNote('${s.key}', this.value)" placeholder="Tuliskan pengalaman belajar murid pada tahapan ${s.title}..." class="w-full text-xs p-2 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-500">${note}</textarea>
            </div>
          `;
          siklusList.appendChild(card);
        });
      }

      calculateRppScoreLive();
    }

    function setBkScore(indId, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.bkScores) guru.bkScores = {};
      guru.bkScores[indId] = score;

      document.querySelectorAll(`.bk-score-btn-${indId}`).forEach(b => {
        b.className = `bk-score-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-slate-100 text-slate-600 hover:bg-slate-200`;
      });
      if (window.event && window.event.target) {
        window.event.target.className = `bk-score-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-indigo-600 text-white shadow-sm`;
      }

      const row = document.getElementById(`bk-telaah-row-${indId}`);
      if (row) {
        row.className = 'bg-white p-3 rounded-xl border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-2.5 text-xs transition-colors';
      }
      const warn = document.getElementById(`bk-telaah-warn-${indId}`);
      if (warn) {
        warn.className = 'hidden';
      }
      const printBadge = document.getElementById(`bk-telaah-print-${indId}`);
      if (printBadge) {
        printBadge.innerText = `Skor: ${score}`;
      }

      calculateRppScoreLive();
      updateSidebarPredikat(guru);
      saveDataToLocalStorage();
    }

    function setBkDlScore(key, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.bkDlScores) guru.bkDlScores = {};
      guru.bkDlScores[key] = score;

      document.querySelectorAll(`.bk-dl-btn-${key}`).forEach(b => {
        b.className = `bk-dl-btn-${key} px-2.5 py-1 rounded text-xs font-bold transition bg-slate-100 text-slate-600 hover:bg-slate-200`;
      });
      if (window.event && window.event.target) {
        window.event.target.className = `bk-dl-btn-${key} px-2.5 py-1 rounded text-xs font-bold transition bg-indigo-600 text-white shadow-sm`;
      }

      const card = document.getElementById(`bk-prinsip-card-${key}`) || document.getElementById(`bk-siklus-card-${key}`);
      if (card) {
        card.className = 'bg-white p-3.5 rounded-xl border border-slate-200 space-y-2.5 text-xs transition-colors';
      }
      const warn = document.getElementById(`bk-prinsip-warn-${key}`) || document.getElementById(`bk-siklus-warn-${key}`);
      if (warn) {
        warn.className = 'hidden';
      }
      const printBadge = document.getElementById(`bk-prinsip-print-${key}`) || document.getElementById(`bk-siklus-print-${key}`);
      if (printBadge) {
        printBadge.innerText = `Skor: ${score}`;
      }

      calculateRppScoreLive();
      updateSidebarPredikat(guru);
      saveDataToLocalStorage();
    }

    function saveBkDlNote(key, val) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.bkDlNotes) guru.bkDlNotes = {};
      guru.bkDlNotes[key] = val;
      saveDataToLocalStorage();
    }

    function onSupervisorChange(val) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (guru) {
        guru.supervisorId = parseInt(val);
        saveDataToLocalStorage();
        showToast('Supervisor penilai diperbarui.');
      }
    }

    function onPraTargetPerilakuChange(targetVal) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      guru.targetPerilaku = targetVal;
      const obsTargetBadge = document.getElementById('obs-target-badge');
      if (obsTargetBadge) obsTargetBadge.innerText = `Fokus: ${targetVal}`;
      const obsFokusPmmText = document.getElementById('obs-fokus-pmm-text');
      if (obsFokusPmmText) obsFokusPmmText.innerText = targetVal;
      const editTarget = document.getElementById('edit-guru-target');
      if (editTarget) editTarget.value = targetVal;
      saveDataToLocalStorage();
      // Auto sync ke server MySQL
      apiCall('save_pra', {
        guruId: guru.id,
        targetPerilaku: targetVal
      }).catch(() => {});
    }

    async function savePraObservasi() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;

      const targetPerilakuVal = document.getElementById('pra-input-target-perilaku')?.value;
      if (targetPerilakuVal) {
        guru.targetPerilaku = targetPerilakuVal;
        const obsTargetBadge = document.getElementById('obs-target-badge');
        if (obsTargetBadge) obsTargetBadge.innerText = `Fokus: ${targetPerilakuVal}`;
        const obsFokusPmmText = document.getElementById('obs-fokus-pmm-text');
        if (obsFokusPmmText) obsFokusPmmText.innerText = targetPerilakuVal;
      }

      let missingCount = 0;
      if (guru.mapel === 'BK') {
        const bkBidang = document.getElementById('pra-bk-bidang')?.value.trim() || '';
        const bkFokus = document.getElementById('pra-bk-fokus')?.value.trim() || '';
        const bkTujuan = document.getElementById('pra-bk-tujuan')?.value.trim() || '';
        guru.bkBidangLayanan = bkBidang;
        guru.bkFokusLayanan = bkFokus;
        guru.bkTujuanLayanan = bkTujuan;
        guru.materiTopik = bkFokus ? (bkBidang ? `${bkBidang}: ${bkFokus}` : bkFokus) : bkBidang;
        guru.tujuanPembelajaran = bkTujuan;
        if (!guru.praFeedback) guru.praFeedback = {};
        guru.praFeedback.bkBidangLayanan = bkBidang;
        guru.praFeedback.bkFokusLayanan = bkFokus;
        guru.praFeedback.bkTujuanLayanan = bkTujuan;

        if (!checkFieldValidation(document.getElementById('pra-bk-bidang'), document.getElementById('pra-warn-bk-bidang'))) missingCount++;
        if (!checkFieldValidation(document.getElementById('pra-bk-fokus'), document.getElementById('pra-warn-bk-fokus'))) missingCount++;
        if (!checkFieldValidation(document.getElementById('pra-bk-tujuan'), document.getElementById('pra-warn-bk-tujuan'))) missingCount++;
        ASPEK_BK_TELAAH.forEach(item => {
          if (!guru.bkScores || guru.bkScores[item.id] === undefined) missingCount++;
        });
      } else {
        guru.materiTopik = document.getElementById('pra-input-materi')?.value || '';
        guru.tujuanPembelajaran = document.getElementById('pra-input-tujuan')?.value || '';
        if (!checkFieldValidation(document.getElementById('pra-input-materi'), document.getElementById('pra-warn-materi'))) missingCount++;
        if (!checkFieldValidation(document.getElementById('pra-input-tujuan'), document.getElementById('pra-warn-tujuan'))) missingCount++;
        DIMENSI_RPP_PM.forEach(dim => {
          dim.indikator.forEach(ind => {
            if (!guru.rppScores || guru.rppScores[ind.id] === undefined) missingCount++;
          });
        });
      }
      guru.tanggalTelaah = document.getElementById('pra-input-tanggal')?.value || '';

      if (!guru.praFeedback) guru.praFeedback = {};
      guru.praFeedback.kekuatan = document.getElementById('pra-fb-kekuatan')?.value || '';
      guru.praFeedback.prioritas = document.getElementById('pra-fb-prioritas')?.value || '';
      guru.praFeedback.refleksi = document.getElementById('pra-fb-refleksi')?.value || '';
      guru.praFeedback.kesepakatan = document.getElementById('pra-fb-kesepakatan')?.value || '';
      guru.praFeedback.waktuBerikutnya = document.getElementById('pra-fb-waktu')?.value || '';

      if (guru.status === 'Belum') guru.status = 'Tindak Lanjut';

      syncSelectedGuru(guru.id);
      saveDataToLocalStorage();

      if (missingCount > 0) {
        showToast(`⚠️ Terdapat ${missingCount} isian/indikator belum diisi! Mohon periksa item bertanda merah.`, true);
        const firstUnfilled = document.querySelector('#view-pra .border-rose-300, #view-pra .border-rose-400');
        if (firstUnfilled) {
          firstUnfilled.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      } else {
        showToast('Hasil Telaah Modul Ajar/RPP lengkap & berhasil disimpan!');
      }

      // Sync ke backend server MySQL
      const res = await apiCall('save_pra', {
        guruId: guru.id,
        materiTopik: guru.materiTopik,
        tujuanPembelajaran: guru.tujuanPembelajaran,
        tanggalTelaah: guru.tanggalTelaah,
        targetPerilaku: guru.targetPerilaku,
        rppScores: guru.rppScores || {},
        bkScores: guru.bkScores || {},
        bkDlScores: guru.bkDlScores || {},
        bkDlNotes: guru.bkDlNotes || {},
        praFeedback: guru.praFeedback || {},
        catatanPra: guru.catatanPra || '',
        supervisorId: guru.supervisorId || 1
      });
      if (res && res.success && isServerOnline && missingCount === 0) {
        showToast(res.message || 'Data Telaah tersimpan di server MySQL!');
      }
    }

    function loadObservasiData() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;

      const instTitle = document.getElementById('obs-inst-title');
      const instSubtitle = document.getElementById('obs-inst-subtitle');
      const scaleLegend = document.getElementById('obs-scale-legend');
      const standaloneDl = document.getElementById('panel-standalone-dl');
      const bannerTag = document.getElementById('obs-tag-banner');
      const obsTargetBadge = document.getElementById('obs-target-badge');
      const obsFokusPmmText = document.getElementById('obs-fokus-pmm-text');
      const targetPerilakuVal = guru.targetPerilaku || 'Instruksi Pembelajaran';
      if (obsTargetBadge) obsTargetBadge.innerText = `Fokus: ${targetPerilakuVal}`;
      if (obsFokusPmmText) obsFokusPmmText.innerText = targetPerilakuVal;

      if (guru.mapel === 'BK') {
        if (bannerTag) bannerTag.innerText = 'Instrumen Observasi Layanan BK (27 Indikator & Deep Learning)';
        if (instTitle) instTitle.innerText = 'Tahap 2: Observasi Kelas (27 Indikator & Deep Learning)';
        if (instSubtitle) instSubtitle.innerText = 'Observasi layanan bimbingan dan konseling berbasis prinsip dan siklus belajar mendalam.';
        if (scaleLegend) {
          scaleLegend.innerText = 'Skala: 1 = Belum tampak, 2 = Mulai berkembang, 3 = Sesuai harapan, 4 = Sangat baik';
          scaleLegend.className = 'text-[11px] font-semibold text-emerald-800 bg-emerald-50 px-2.5 py-1 rounded-lg border border-emerald-200';
        }
        if (standaloneDl) standaloneDl.style.display = 'none';
        renderBkObservasi27(guru);
      } else {
        if (bannerTag) bannerTag.innerText = 'Instrumen Observasi Kelas';
        if (instTitle) instTitle.innerText = 'Instrumen 28 Indikator (7 Aspek Pembelajaran)';
        if (instSubtitle) instSubtitle.innerText = 'Observasi pelaksanaan pembelajaran di kelas.';
        if (scaleLegend) {
          scaleLegend.innerText = 'Skala: 1 (Kurang), 2 (Cukup), 3 (Baik), 4 (Sangat Baik)';
          scaleLegend.className = 'text-[11px] font-semibold text-indigo-700 bg-indigo-50 px-2.5 py-1 rounded-lg border border-indigo-200';
        }
        if (standaloneDl) standaloneDl.style.display = 'block';

        render28Indikator();

        ['mindful', 'meaningful', 'joyful', 'memahami', 'mengaplikasi', 'merefleksi'].forEach(k => {
          const val = (guru.deepLearning && guru.deepLearning[k]) || 0;
          updateDlScoreButtons(k, val);
        });
      }

      const obsCatatanFakta = document.getElementById('obs-catatan-fakta');
      if (obsCatatanFakta) {
        obsCatatanFakta.value = guru.catatanFakta || '';
        checkFieldValidation(obsCatatanFakta, document.getElementById('obs-warn-catatan-fakta'));
      }

      calculateObsScoreLive();
      syncAllSignatures(guru);
    }

    function render28Indikator() {
      const container = document.getElementById('indikator-container');
      if (!container) return;
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      container.innerHTML = '';

      ASPEK_OBSERVASI.forEach(aspek => {
        const card = document.createElement('div');
        card.className = 'bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-3';

        let indRows = aspek.indikator.map(ind => {
          const score = (guru && guru.obsScores && guru.obsScores[ind.id] !== undefined) ? guru.obsScores[ind.id] : 0;
          const isUnfilled = !score || score === 0;
          return `
            <div id="obs-ind-row-${ind.id}" class="${isUnfilled ? 'bg-rose-50/60 border-rose-300' : 'bg-white border-slate-200'} p-3 rounded-lg border flex flex-col md:flex-row md:items-center justify-between gap-2 text-xs transition-colors">
              <div class="flex items-center space-x-2 flex-1">
                <span class="font-medium text-slate-700">${ind.id}. ${ind.text}</span>
                <span id="obs-warn-${ind.id}" class="${isUnfilled ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print flex-shrink-0">
                  <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                  <span>Belum Diisi</span>
                </span>
              </div>
              <div class="flex items-center space-x-2 flex-shrink-0">
                <span id="obs-print-${ind.id}" class="print-score-badge">${score > 0 ? 'Skor: ' + score : 'Skor: -'}</span>
                <div class="flex items-center space-x-1.5" id="obs-ind-btn-${ind.id}">
                  ${[1, 2, 3, 4].map(s => `
                    <button type="button" onclick="setIndikatorScore(${ind.id}, ${s})" class="ind-btn-${ind.id} px-2.5 py-1 rounded text-xs font-bold transition ${score === s ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                      ${s}
                    </button>
                  `).join('')}
                </div>
              </div>
            </div>
          `;
        }).join('');

        card.innerHTML = `
          <h5 class="font-bold text-xs text-indigo-950 flex items-center space-x-2">
            <span class="w-2 h-2 rounded-full bg-indigo-600"></span>
            <span>${aspek.nama}</span>
          </h5>
          <div class="space-y-2">${indRows}</div>
        `;
        container.appendChild(card);
      });
    }

    function renderBkObservasi27(guru) {
      const container = document.getElementById('indikator-container');
      if (!container) return;
      container.innerHTML = '';

      if (!guru.obsScores) guru.obsScores = {};
      if (!guru.obsNotes) guru.obsNotes = {};

      const scaleLabels = {
        1: '1: Belum tampak',
        2: '2: Mulai berkembang',
        3: '3: Sesuai harapan',
        4: '4: Sangat baik'
      };

      ASPEK_BK_OBSERVASI.forEach(grup => {
        const card = document.createElement('div');
        card.className = 'bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-3.5';

        let innerContent = '';

        if (grup.subkelompok) {
          innerContent = grup.subkelompok.map(sub => {
            const indRows = sub.indikator.map(ind => renderBkIndikatorItem(ind, guru, scaleLabels)).join('');
            return `
              <div class="bg-white/80 p-3.5 rounded-xl border border-slate-200/80 space-y-2.5">
                <div class="border-b border-slate-200 pb-1.5">
                  <h6 class="font-bold text-xs text-indigo-900">${sub.namaSub}</h6>
                  <p class="text-[11px] text-slate-500 italic">${sub.tujuanSub}</p>
                </div>
                <div class="space-y-2.5">${indRows}</div>
              </div>
            `;
          }).join('');
        } else {
          innerContent = grup.indikator.map(ind => renderBkIndikatorItem(ind, guru, scaleLabels)).join('');
        }

        card.innerHTML = `
          <div class="border-b border-slate-200 pb-2">
            <h5 class="font-bold text-xs text-indigo-950 flex items-center space-x-2">
              <span class="w-2.5 h-2.5 rounded-full bg-emerald-600"></span>
              <span>${grup.nama}</span>
            </h5>
            <p class="text-[11px] text-slate-500 mt-0.5">${grup.deskripsi}</p>
          </div>
          <div class="space-y-3">${innerContent}</div>
        `;
        container.appendChild(card);
      });
    }

    function renderBkIndikatorItem(ind, guru, scaleLabels) {
      const score = (guru.obsScores && guru.obsScores[ind.id] !== undefined) ? guru.obsScores[ind.id] : 0;
      const note = (guru.obsNotes && guru.obsNotes[ind.id]) ? guru.obsNotes[ind.id] : '';
      const isUnfilled = !score || score === 0;

      return `
        <div id="bk-obs-row-${ind.id}" class="${isUnfilled ? 'bg-rose-50/60 border-rose-300' : 'bg-white border-slate-200'} p-3 rounded-lg border space-y-2 text-xs transition-colors">
          <div class="flex flex-col md:flex-row md:items-center justify-between gap-2">
            <div class="flex-1 pr-2 flex items-center space-x-2">
              <span class="font-bold text-slate-800">${ind.id}.</span>
              <span class="text-slate-700 ml-1 font-medium">${ind.text}</span>
              <span id="bk-warn-${ind.id}" class="${isUnfilled ? 'inline-flex' : 'hidden'} text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print flex-shrink-0">
                <i class="fa-solid fa-triangle-exclamation text-rose-500"></i>
                <span>Belum Diisi</span>
              </span>
            </div>
            <div class="flex items-center space-x-2 flex-shrink-0">
              <span id="bk-print-${ind.id}" class="print-score-badge">${score > 0 ? 'Skor: ' + score : 'Skor: -'}</span>
              <div class="flex items-center space-x-1.5" id="bk-obs-btn-group-${ind.id}">
                ${[1, 2, 3, 4].map(s => `
                  <button type="button" onclick="setBkObservasiScore(${ind.id}, ${s})" title="${scaleLabels[s]}" class="bk-obs-btn-${ind.id} px-2.5 py-1 rounded text-xs font-bold transition ${score === s ? 'bg-emerald-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                    ${s}
                  </button>
                `).join('')}
              </div>
            </div>
          </div>
          <div class="pt-1 border-t border-slate-100">
            <input type="text" value="${note.replace(/"/g, '&quot;')}" oninput="saveBkObservasiNote(${ind.id}, this.value)" placeholder="Bukti observasi / catatan fakta layanan butir ${ind.id}..." class="w-full text-[11px] px-2.5 py-1.5 rounded-lg border border-slate-200 bg-slate-50/50 focus:bg-white focus:outline-none focus:ring-1 focus:ring-emerald-500">
          </div>
        </div>
      `;
    }

    function setBkObservasiScore(indId, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.obsScores) guru.obsScores = {};
      guru.obsScores[indId] = score;

      document.querySelectorAll(`.bk-obs-btn-${indId}`).forEach(b => {
        b.className = `bk-obs-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-slate-100 text-slate-600 hover:bg-slate-200`;
      });
      if (window.event && window.event.target) {
        window.event.target.className = `bk-obs-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-emerald-600 text-white shadow-sm`;
      }

      const row = document.getElementById(`bk-obs-row-${indId}`);
      if (row) {
        row.className = 'bg-white p-3 rounded-lg border border-slate-200 space-y-2 text-xs transition-colors';
      }
      const warn = document.getElementById(`bk-warn-${indId}`);
      if (warn) {
        warn.className = 'hidden';
      }
      const printBadge = document.getElementById(`bk-print-${indId}`);
      if (printBadge) {
        printBadge.innerText = `Skor: ${score}`;
      }

      calculateObsScoreLive();
      updateSidebarPredikat(guru);
      saveDataToLocalStorage();
    }

    function saveBkObservasiNote(indId, noteVal) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.obsNotes) guru.obsNotes = {};
      guru.obsNotes[indId] = noteVal;
      saveDataToLocalStorage();
    }

    function setIndikatorScore(indId, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.obsScores) guru.obsScores = {};
      guru.obsScores[indId] = score;

      document.querySelectorAll(`.ind-btn-${indId}`).forEach(b => {
        b.className = `ind-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-slate-100 text-slate-600 hover:bg-slate-200`;
      });
      if (window.event && window.event.target) {
        window.event.target.className = `ind-btn-${indId} px-2.5 py-1 rounded text-xs font-bold transition bg-indigo-600 text-white shadow-sm`;
      }

      const row = document.getElementById(`obs-ind-row-${indId}`);
      if (row) {
        row.className = 'bg-white p-3 rounded-lg border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-2 text-xs transition-colors';
      }
      const warn = document.getElementById(`obs-warn-${indId}`);
      if (warn) {
        warn.className = 'hidden';
      }
      const printBadge = document.getElementById(`obs-print-${indId}`);
      if (printBadge) {
        printBadge.innerText = `Skor: ${score}`;
      }

      calculateObsScoreLive();
      updateSidebarPredikat(guru);
      saveDataToLocalStorage();
    }

    function calculateObsScoreLive() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      const metrics = getGuruEvaluationMetrics(guru);

      const liveScore = document.getElementById('obs-live-score');
      const predBadge = document.getElementById('obs-predikat-badge');

      if (liveScore) liveScore.innerText = `${metrics.obsPct}%`;
      if (predBadge) {
        predBadge.innerText = metrics.predikat;
        predBadge.className = `px-2.5 py-1 rounded-lg text-xs font-bold ${metrics.badgeColor}`;
      }
    }

    function setDlScore(aspectKey, score) {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.deepLearning) guru.deepLearning = {};
      guru.deepLearning[aspectKey] = score;

      updateDlScoreButtons(aspectKey, score);
      saveDataToLocalStorage();
      showToast(`Dimensi ${aspectKey} dinilai: ${score}`);
    }

    function updateDlScoreButtons(aspectKey, activeScore) {
      const group = document.getElementById(`dl-score-${aspectKey}`);
      const row = document.getElementById(`dl-row-${aspectKey}`);
      const warn = document.getElementById(`dl-warn-${aspectKey}`);
      const printEl = document.getElementById(`dl-print-${aspectKey}`);

      if (activeScore && activeScore > 0) {
        if (row) {
          row.className = 'flex items-center justify-between bg-white p-2 rounded-lg border border-slate-200 transition-colors';
        }
        if (warn) {
          warn.className = 'hidden';
        }
        if (printEl) {
          printEl.innerText = `Skor: ${activeScore}`;
        }
      } else {
        if (row) {
          row.className = 'flex items-center justify-between bg-rose-50/60 p-2 rounded-lg border border-rose-300 transition-colors';
        }
        if (warn) {
          warn.className = 'inline-flex text-[10px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded items-center space-x-1 no-print';
        }
        if (printEl) {
          printEl.innerText = 'Skor: -';
        }
      }

      if (!group) return;
      group.querySelectorAll('button').forEach((btn, idx) => {
        const val = idx + 1;
        if (val === activeScore) {
          btn.className = 'w-6 h-6 rounded text-[10px] font-bold bg-indigo-600 text-white shadow-sm';
        } else {
          btn.className = 'w-6 h-6 rounded text-[10px] font-bold bg-slate-100 text-slate-600 hover:bg-indigo-500 hover:text-white';
        }
      });
    }

    async function saveObservasi() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;

      const obsCatatanFakta = document.getElementById('obs-catatan-fakta');
      if (obsCatatanFakta) guru.catatanFakta = obsCatatanFakta.value;

      let missingCount = 0;
      if (guru.mapel === 'BK') {
        ASPEK_BK_OBSERVASI.forEach(grup => {
          const list = grup.subkelompok ? grup.subkelompok.flatMap(s => s.indikator) : grup.indikator;
          list.forEach(ind => {
            if (!guru.obsScores || !guru.obsScores[ind.id] || guru.obsScores[ind.id] === 0) {
              missingCount++;
            }
          });
        });
      } else {
        ['mindful', 'meaningful', 'joyful', 'memahami', 'mengaplikasi', 'merefleksi'].forEach(k => {
          if (!guru.deepLearning || !guru.deepLearning[k] || guru.deepLearning[k] === 0) {
            missingCount++;
          }
        });
        ASPEK_OBSERVASI.forEach(aspek => {
          aspek.indikator.forEach(ind => {
            if (!guru.obsScores || !guru.obsScores[ind.id] || guru.obsScores[ind.id] === 0) {
              missingCount++;
            }
          });
        });
      }

      const isCatatanFilled = checkFieldValidation(obsCatatanFakta, document.getElementById('obs-warn-catatan-fakta'));
      if (!isCatatanFilled) missingCount++;

      guru.status = 'Selesai';
      syncSelectedGuru(guru.id);
      saveDataToLocalStorage();

      if (missingCount > 0) {
        showToast(`⚠️ Terdapat ${missingCount} item belum diisi! Mohon periksa item bertanda merah.`, true);
        const firstUnfilled = document.querySelector('#view-observasi .border-rose-300, #view-observasi .border-rose-400');
        if (firstUnfilled) {
          firstUnfilled.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      } else {
        showToast('Hasil Observasi Kelas lengkap & berhasil disimpan!');
      }

      // Sync ke MySQL Server
      const res = await apiCall('save_obs', {
        guruId: guru.id,
        obsScores: guru.obsScores || {},
        obsNotes: guru.obsNotes || {},
        deepLearning: guru.deepLearning || {},
        catatanFakta: guru.catatanFakta || ''
      });
      if (res && res.success && isServerOnline && missingCount === 0) {
        showToast(res.message || 'Hasil Observasi tersimpan di server MySQL!');
      }
    }

    function loadCoachingData() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.coaching) guru.coaching = {};

      const tEl = document.getElementById('coach-tujuan');
      const iEl = document.getElementById('coach-identifikasi');
      const rEl = document.getElementById('coach-rencana');
      const taEl = document.getElementById('coach-tanggungjawab');

      if (tEl) tEl.value = guru.coaching.tujuan || '';
      if (iEl) iEl.value = guru.coaching.identifikasi || '';
      if (rEl) rEl.value = guru.coaching.rencana || '';
      if (taEl) taEl.value = guru.coaching.tanggungJawab || '';

      checkFieldValidation(tEl, document.getElementById('coach-warn-tujuan'));
      checkFieldValidation(iEl, document.getElementById('coach-warn-identifikasi'));
      checkFieldValidation(rEl, document.getElementById('coach-warn-rencana'));
      checkFieldValidation(taEl, document.getElementById('coach-warn-tanggungjawab'));

      syncAllSignatures(guru);
    }

    async function saveCoaching() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!guru.coaching) guru.coaching = {};

      const tEl = document.getElementById('coach-tujuan');
      const iEl = document.getElementById('coach-identifikasi');
      const rEl = document.getElementById('coach-rencana');
      const taEl = document.getElementById('coach-tanggungjawab');

      guru.coaching.tujuan = tEl?.value || '';
      guru.coaching.identifikasi = iEl?.value || '';
      guru.coaching.rencana = rEl?.value || '';
      guru.coaching.tanggungJawab = taEl?.value || '';

      let missingCount = 0;
      if (!checkFieldValidation(tEl, document.getElementById('coach-warn-tujuan'))) missingCount++;
      if (!checkFieldValidation(iEl, document.getElementById('coach-warn-identifikasi'))) missingCount++;
      if (!checkFieldValidation(rEl, document.getElementById('coach-warn-rencana'))) missingCount++;
      if (!checkFieldValidation(taEl, document.getElementById('coach-warn-tanggungjawab'))) missingCount++;

      saveDataToLocalStorage();

      if (missingCount > 0) {
        showToast(`⚠️ Terdapat ${missingCount} isian TIRTA belum diisi! Mohon periksa tanda merah.`, true);
        const firstUnfilled = document.querySelector('#view-coaching .border-rose-400');
        if (firstUnfilled) {
          firstUnfilled.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      } else {
        showToast('Catatan Sesi Coaching TIRTA lengkap & berhasil disimpan!');
      }

      // Sync ke MySQL Server
      const res = await apiCall('save_coaching', {
        guruId: guru.id,
        tujuan: guru.coaching.tujuan,
        identifikasi: guru.coaching.identifikasi,
        rencana: guru.coaching.rencana,
        tanggungJawab: guru.coaching.tanggungJawab
      });
      if (res && res.success && isServerOnline && missingCount === 0) {
        showToast(res.message || 'Catatan Coaching tersimpan di server MySQL!');
      }
    }

    // ============================================================
    // SINKRONISASI TANDA TANGAN 3 PIHAK LENGKAP PADA SELURUH MENU CETAK
    // (Guru Yang Disupervisi, Supervisor Penilai, Mengetahui Kepala Sekolah)
    // ============================================================
    function syncAllSignatures(guru) {
      if (!guru) guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;

      const spvObj = appSettings.supervisors.find(s => s.id === guru.supervisorId);
      const spvNama = spvObj ? spvObj.nama.replace(/\s*\(Supervisor\s*\d+\)/i, '').trim() : 'Supervisor';
      const spvNip = spvObj ? (spvObj.nip ? `NIP. ${spvObj.nip}` : 'NIP. -') : 'NIP. -';
      const ksNama = (appSettings.kepalaSekolah && appSettings.kepalaSekolah.nama) ? appSettings.kepalaSekolah.nama : 'Drs. Teguh Edy Purwanta';
      const ksNip = (appSettings.kepalaSekolah && appSettings.kepalaSekolah.nip) ? `NIP. ${appSettings.kepalaSekolah.nip}` : 'NIP. -';
      const todayFormatted = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

      // 1. Tanda Tangan Pra-Observasi (Lembar Telaah)
      const praDateEl = document.getElementById('pra-ttd-date');
      if (praDateEl) praDateEl.innerText = guru.tanggalTelaah ? new Date(guru.tanggalTelaah).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }) : todayFormatted;
      const praGuru = document.getElementById('pra-ttd-guru');
      const praNipGuru = document.getElementById('pra-ttd-nip-guru');
      if (praGuru) praGuru.innerText = guru.nama;
      if (praNipGuru) praNipGuru.innerText = `NIP. ${guru.nip || '-'}`;
      const praSpv = document.getElementById('pra-ttd-spv');
      const praNipSpv = document.getElementById('pra-ttd-nip-spv');
      if (praSpv) praSpv.innerText = spvNama;
      if (praNipSpv) praNipSpv.innerText = spvNip;
      const praKs = document.getElementById('pra-ttd-ks');
      const praNipKs = document.getElementById('pra-ttd-nip-ks');
      if (praKs) praKs.innerText = ksNama;
      if (praNipKs) praNipKs.innerText = ksNip;

      // 2. Tanda Tangan Observasi Kelas
      const obsDateEl = document.getElementById('obs-ttd-date');
      if (obsDateEl) obsDateEl.innerText = guru.tanggalObservasi ? new Date(guru.tanggalObservasi).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }) : todayFormatted;
      const obsGuru = document.getElementById('obs-ttd-guru');
      const obsNipGuru = document.getElementById('obs-ttd-nip-guru');
      if (obsGuru) obsGuru.innerText = guru.nama;
      if (obsNipGuru) obsNipGuru.innerText = `NIP. ${guru.nip || '-'}`;
      const obsSpv = document.getElementById('obs-ttd-spv');
      const obsNipSpv = document.getElementById('obs-ttd-nip-spv');
      if (obsSpv) obsSpv.innerText = spvNama;
      if (obsNipSpv) obsNipSpv.innerText = spvNip;
      const obsKs = document.getElementById('obs-ttd-ks');
      const obsNipKs = document.getElementById('obs-ttd-nip-ks');
      if (obsKs) obsKs.innerText = ksNama;
      if (obsNipKs) obsNipKs.innerText = ksNip;

      // 3. Tanda Tangan Pasca-Observasi (Coaching TIRTA)
      const coachDateEl = document.getElementById('coach-ttd-date');
      if (coachDateEl) coachDateEl.innerText = todayFormatted;
      const coachGuru = document.getElementById('coach-ttd-guru');
      const coachNipGuru = document.getElementById('coach-ttd-nip-guru');
      if (coachGuru) coachGuru.innerText = guru.nama;
      if (coachNipGuru) coachNipGuru.innerText = `NIP. ${guru.nip || '-'}`;
      const coachSpv = document.getElementById('coach-ttd-spv');
      const coachNipSpv = document.getElementById('coach-ttd-nip-spv');
      if (coachSpv) coachSpv.innerText = spvNama;
      if (coachNipSpv) coachNipSpv.innerText = spvNip;
      const coachKs = document.getElementById('coach-ttd-ks');
      const coachNipKs = document.getElementById('coach-ttd-nip-ks');
      if (coachKs) coachKs.innerText = ksNama;
      if (coachNipKs) coachNipKs.innerText = ksNip;

      // 4. Tanda Tangan Laporan Individu
      const lapDateEl = document.getElementById('lap-report-date');
      if (lapDateEl) lapDateEl.innerText = todayFormatted;
      const lapGuru = document.getElementById('lap-ttd-guru');
      const lapNipGuru = document.getElementById('lap-ttd-nip-guru');
      if (lapGuru) lapGuru.innerText = guru.nama;
      if (lapNipGuru) lapNipGuru.innerText = `NIP. ${guru.nip || '-'}`;
      const lapSpv = document.getElementById('lap-ttd-spv');
      const lapNipSpv = document.getElementById('lap-ttd-nip-spv');
      if (lapSpv) lapSpv.innerText = spvNama;
      if (lapNipSpv) lapNipSpv.innerText = spvNip;
      const lapKs = document.getElementById('lap-ttd-ks');
      const lapNipKs = document.getElementById('lap-ttd-nip-ks');
      if (lapKs) lapKs.innerText = ksNama;
      if (lapNipKs) lapNipKs.innerText = ksNip;
    }

    // ============================================================
    // FUNGSI RESET / KOSONGKAN ISIAN FORMULIR PENILAIAN
