      saveDataToLocalStorage();
      showToast('Instrumen Observasi Kelas berhasil dikosongkan!');
    }

    function resetCoaching() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId);
      if (!guru) return;
      if (!confirm(`Apakah Anda yakin ingin mengosongkan seluruh catatan percakapan Coaching TIRTA untuk ${guru.nama}?`)) return;

      guru.coaching = { tujuan: '', identifikasi: '', rencana: '', tanggungJawab: '' };

      loadCoachingData();
      saveDataToLocalStorage();
      showToast('Catatan Coaching TIRTA berhasil dikosongkan!');
    }

    function updateReportView() {
      const guru = guruDatabase.find(g => g.id === selectedGuruId) || guruDatabase[0];
      if (!guru) return;

      const spv = appSettings.supervisors.find(s => s.id === guru.supervisorId) || appSettings.supervisors[0];
      const metrics = getGuruEvaluationMetrics(guru);

      document.getElementById('kop-nama-sekolah').innerText = appSettings.sekolah;
      document.getElementById('kop-periode').innerText = appSettings.periode;

      document.getElementById('lap-disp-nama').innerText = guru.nama;
      document.getElementById('lap-disp-nip').innerText = guru.nip;
      document.getElementById('lap-disp-mapel').innerText = guru.mapel;
      document.getElementById('lap-disp-kelas').innerText = guru.kelas;
      document.getElementById('lap-disp-spv').innerText = spv ? spv.nama.split('(')[0].trim() : '-';
      document.getElementById('lap-disp-target').innerText = guru.targetPerilaku || 'Instruksi Pembelajaran';

      const lapDocLabel = document.getElementById('lap-label-doc-perencanaan');
      const lapObsLabel = document.getElementById('lap-label-observasi');

      if (guru.mapel === 'BK') {
        if (lapDocLabel) lapDocLabel.innerText = 'Telaah Dokumen Perencanaan Pelayanan (Modul Pelayanan BK - 14 Aspek & Deep Learning)';
        if (lapObsLabel) lapObsLabel.innerText = 'Observasi Layanan BK (27 Indikator & Deep Learning)';
      } else {
        if (lapDocLabel) lapDocLabel.innerText = 'Telaah Modul Ajar/RPP Berbasis Pembelajaran Mendalam (30 Indikator dlm 6 Dimensi)';
        if (lapObsLabel) lapObsLabel.innerText = 'Observasi Kinerja Kelas (28 Indikator & 7 Aspek)';
      }

      document.getElementById('lap-skor-rpp').innerText = `${metrics.rppPct}%`;
      document.getElementById('lap-pred-rpp').innerText = metrics.rppPct >= 80 ? 'Baik / Sangat Baik' : 'Cukup';

      document.getElementById('lap-skor-obs').innerText = `${metrics.obsPct}%`;
      document.getElementById('lap-pred-obs').innerText = metrics.obsPct >= 80 ? 'Baik / Sangat Baik' : 'Cukup';

      document.getElementById('lap-skor-akhir').innerText = `${metrics.finalScore}%`;
      document.getElementById('lap-pred-akhir').innerText = metrics.predikat;

      document.getElementById('lap-disp-fakta').innerText = guru.catatanFakta || 'Belum ada catatan obyektif.';

      const dlBadges = document.getElementById('lap-disp-dl-badges');
      if (dlBadges) {
        if (guru.mapel === 'BK') {
          dlBadges.innerHTML = `
            <span class="px-2 py-0.5 rounded bg-emerald-100 text-emerald-800 font-semibold">Instrumen BK: 27 Indikator Terintegrasi Deep Learning</span>
            <span class="px-2 py-0.5 rounded bg-indigo-100 text-indigo-800 font-semibold">Model TIRTA</span>
          `;
        } else {
          const dl = guru.deepLearning || {};
          dlBadges.innerHTML = `
            <span class="px-2 py-0.5 rounded bg-indigo-100 text-indigo-800 font-semibold">Mindful: ${dl.mindful || 0}/4</span>
            <span class="px-2 py-0.5 rounded bg-indigo-100 text-indigo-800 font-semibold">Meaningful: ${dl.meaningful || 0}/4</span>
            <span class="px-2 py-0.5 rounded bg-indigo-100 text-indigo-800 font-semibold">Joyful: ${dl.joyful || 0}/4</span>
            <span class="px-2 py-0.5 rounded bg-emerald-100 text-emerald-800 font-semibold">Memahami: ${dl.memahami || 0}/4</span>
            <span class="px-2 py-0.5 rounded bg-emerald-100 text-emerald-800 font-semibold">Mengaplikasi: ${dl.mengaplikasi || 0}/4</span>
            <span class="px-2 py-0.5 rounded bg-emerald-100 text-emerald-800 font-semibold">Merefleksi: ${dl.merefleksi || 0}/4</span>
          `;
        }
      }

      document.getElementById('lap-disp-rencana').innerText = (guru.coaching && guru.coaching.rencana) ? guru.coaching.rencana : 'Belum diisi.';
      document.getElementById('lap-disp-komitmen').innerText = (guru.coaching && guru.coaching.tanggungJawab) ? guru.coaching.tanggungJawab : 'Belum diisi.';

      document.getElementById('lap-ttd-guru').innerText = guru.nama;
      document.getElementById('lap-ttd-nip-guru').innerText = `NIP. ${guru.nip}`;

      document.getElementById('lap-ttd-spv').innerText = spv ? spv.nama.split('(')[0].trim() : 'Supervisor Penilai';
      document.getElementById('lap-ttd-nip-spv').innerText = spv ? `NIP. ${spv.nip}` : 'NIP. -';

      document.getElementById('lap-ttd-ks').innerText = appSettings.kepalaSekolah.nama;
      document.getElementById('lap-ttd-nip-ks').innerText = `NIP. ${appSettings.kepalaSekolah.nip}`;
    }

    function setRekapMode(mode) {
      rekapFilterMode = mode;
      const bSemua = document.getElementById('btn-rekap-semua');
      const bSpv = document.getElementById('btn-rekap-spv');
      const bCapaian = document.getElementById('btn-rekap-capaian');
      const sSpv = document.getElementById('rekap-select-supervisor');
      const sCapaian = document.getElementById('rekap-select-capaian');

      bSemua.className = 'px-3 py-1 rounded-md text-slate-600 hover:text-slate-900 transition';
      bSpv.className = 'px-3 py-1 rounded-md text-slate-600 hover:text-slate-900 transition';
      bCapaian.className = 'px-3 py-1 rounded-md text-slate-600 hover:text-slate-900 transition';

      if (sSpv) sSpv.classList.add('hidden');
      if (sCapaian) sCapaian.classList.add('hidden');

      if (mode === 'semua') {
        bSemua.className = 'px-3 py-1 rounded-md bg-white text-indigo-700 font-bold shadow-sm transition';
      } else if (mode === 'supervisor') {
        bSpv.className = 'px-3 py-1 rounded-md bg-white text-indigo-700 font-bold shadow-sm transition';
        if (sSpv) sSpv.classList.remove('hidden');
      } else if (mode === 'capaian') {
        bCapaian.className = 'px-3 py-1 rounded-md bg-white text-indigo-700 font-bold shadow-sm transition';
        if (sCapaian) sCapaian.classList.remove('hidden');
      }

      renderRekapTable();
    }

    function getRekapFilteredTeachers() {
      if (currentRole === 'guru') {
        return guruDatabase.filter(g => g.id === selectedGuruId);
      }

      if (currentRole === 'supervisor') {
        const isPengawasAtauKS = currentLoggedInUser && (
          currentLoggedInUser.is_superadmin ||
          currentLoggedInUser.nip === '196808061998021005' ||
          currentLoggedInUser.nip === '196710202000031006'
        );

        if (isPengawasAtauKS) {
          if (rekapFilterMode === 'supervisor') {
            const sVal = parseInt(document.getElementById('rekap-select-supervisor')?.value) || 1;
            return guruDatabase.filter(g => g.supervisorId === sVal);
          } else if (rekapFilterMode === 'capaian') {
            const cVal = document.getElementById('rekap-select-capaian')?.value || 'Sangat Baik';
            return guruDatabase.filter(g => {
              const m = getGuruEvaluationMetrics(g);
              return m.predikat.includes(cVal);
            });
          }
          return guruDatabase;
        }

        const spvId = (currentLoggedInUser && currentLoggedInUser.id) ? currentLoggedInUser.id : 1;
        return guruDatabase.filter(g => g.supervisorId === spvId);
      }

      if (rekapFilterMode === 'supervisor') {
        const sVal = parseInt(document.getElementById('rekap-select-supervisor')?.value) || 1;
        return guruDatabase.filter(g => g.supervisorId === sVal);
      } else if (rekapFilterMode === 'capaian') {
        const cVal = document.getElementById('rekap-select-capaian')?.value || 'Sangat Baik';
        return guruDatabase.filter(g => {
          const m = getGuruEvaluationMetrics(g);
          return m.predikat.includes(cVal);
        });
      }

      return guruDatabase;
    }

    function renderRekapTable() {
      const panel = document.getElementById('panel-rekap-laporan');
      if (!panel) return;

      if (currentRole === 'guru') {
        panel.classList.add('hidden');
        return;
      }
      panel.classList.remove('hidden');

      const heading = document.getElementById('rekap-title-heading');
      const subtitle = document.getElementById('rekap-desc-subtitle');
      const superControls = document.getElementById('superadmin-rekap-controls');

      if (currentRole === 'supervisor') {
        const isPengawasAtauKS = currentLoggedInUser && (
          currentLoggedInUser.is_superadmin ||
          currentLoggedInUser.nip === '196808061998021005' ||
          currentLoggedInUser.nip === '196710202000031006'
        );
        const spvName = (currentLoggedInUser && currentLoggedInUser.nama) ? currentLoggedInUser.nama.split('(')[0] : 'Supervisor';
        if (isPengawasAtauKS) {
          const isPengawas = currentLoggedInUser && currentLoggedInUser.nip === '196808061998021005';
          if (heading) heading.innerText = isPengawas ? `Rekapitulasi Pengawasan Seluruh Guru (Pengawas: ${spvName})` : `Rekapitulasi Supervisi Sekolah (Kepala Sekolah: ${spvName})`;
          if (subtitle) subtitle.innerText = 'Pemantauan komprehensif capaian seluruh guru binaan SMP Negeri 24 Malang.';
          if (superControls) superControls.classList.remove('hidden');
        } else {
          if (heading) heading.innerText = `Rekapitulasi Binaan: ${spvName}`;
          if (subtitle) subtitle.innerText = 'Menampilkan hasil evaluasi dan kemajuan khusus guru yang Anda supervisi.';
          if (superControls) superControls.classList.add('hidden');
        }
      } else {
        if (heading) heading.innerText = 'Rekapitulasi Supervisi Seluruh Sekolah (Superadmin)';
        if (subtitle) subtitle.innerText = 'Pemetaan capaian kinerja seluruh guru berdasarkan supervisor, predikat, dan rekap kolektif.';
        if (superControls) superControls.classList.remove('hidden');
      }

      const list = getRekapFilteredTeachers();
      const tbody = document.getElementById('rekap-table-tbody');
      if (!tbody) return;
      tbody.innerHTML = '';

      let totRpp = 0, totObs = 0, totFinal = 0;

      if (list.length === 0) {
        tbody.innerHTML = `<tr><td colspan="10" class="text-center py-6 text-slate-400">Tidak ada data guru untuk kriteria rekapitulasi ini.</td></tr>`;
      } else {
        list.forEach((g, idx) => {
          const m = getGuruEvaluationMetrics(g);
          const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);
          totRpp += m.rppPct;
          totObs += m.obsPct;
          totFinal += m.finalScore;

          const tr = document.createElement('tr');
          tr.className = 'hover:bg-slate-50 transition';
          tr.innerHTML = `
            <td class="py-2.5 px-3 font-medium text-slate-500">${idx + 1}</td>
            <td class="py-2.5 px-3">
              <span class="font-bold text-slate-800 block">${g.nama}</span>
              <span class="text-[10px] text-slate-400">NIP. ${g.nip}</span>
            </td>
            <td class="py-2.5 px-3 text-slate-700">${g.mapel}</td>
            <td class="py-2.5 px-3 text-slate-700">${g.kelas}</td>
            <td class="py-2.5 px-3 text-slate-600 text-[11px]">${spv ? spv.nama.split('(')[0] : '-'}</td>
            <td class="py-2.5 px-3 text-center font-semibold text-indigo-600">${m.rppPct}%</td>
            <td class="py-2.5 px-3 text-center font-semibold text-blue-600">${m.obsPct}%</td>
            <td class="py-2.5 px-3 text-center font-bold text-emerald-600">${m.finalScore}%</td>
            <td class="py-2.5 px-3 text-center">
              <span class="px-2 py-0.5 rounded text-[10px] font-bold ${m.badgeColor}">${m.predikat}</span>
            </td>
            <td class="py-2.5 px-3 text-center">
              <button onclick="pilihDanLihatLaporan(${g.id})" class="px-2 py-1 rounded bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-semibold text-[11px] transition">
                Buka Lembar
              </button>
            </td>
          `;
          tbody.appendChild(tr);
        });
      }

      const count = list.length;
      document.getElementById('rekap-stat-count').innerText = count;
      document.getElementById('rekap-stat-rpp').innerText = count > 0 ? `${Math.round(totRpp / count)}%` : '0%';
      document.getElementById('rekap-stat-obs').innerText = count > 0 ? `${Math.round(totObs / count)}%` : '0%';
      document.getElementById('rekap-stat-final').innerText = count > 0 ? `${Math.round(totFinal / count)}%` : '0%';
    }

    function pilihDanLihatLaporan(id) {
      syncSelectedGuru(id);
      document.getElementById('printable-report')?.scrollIntoView({ behavior: 'smooth' });
      showToast('Lembar cetak dialihkan ke guru terpilih.');
    }

    function renderGuruTable() {
      const searchVal = (document.getElementById('guru-search')?.value || '').toLowerCase();
      const filterMapel = document.getElementById('guru-filter-mapel')?.value || '';
      const filterStatus = document.getElementById('guru-filter-status')?.value || '';

      const baseList = getSupervisorTeachers();
      const filtered = baseList.filter(g => {
        const matchSearch = g.nama.toLowerCase().includes(searchVal) || g.nip.includes(searchVal);
        const matchMapel = !filterMapel || g.mapel === filterMapel;
        const matchStatus = !filterStatus || g.status === filterStatus;
        return matchSearch && matchMapel && matchStatus;
      });

      const totalItems = filtered.length;
      const totalPages = Math.ceil(totalItems / guruPageSize) || 1;
      if (guruCurrentPage > totalPages) guruCurrentPage = 1;

      const startIdx = (guruCurrentPage - 1) * guruPageSize;
      const paged = filtered.slice(startIdx, startIdx + guruPageSize);

      const tbody = document.getElementById('guru-table-tbody');
      if (!tbody) return;
      tbody.innerHTML = '';

      const thCheckAll = document.getElementById('th-check-all');
      if (thCheckAll) {
        if (currentRole === 'superadmin') thCheckAll.classList.remove('hidden');
        else thCheckAll.classList.add('hidden');
      }

      if (paged.length === 0) {
        const colSpanCount = currentRole === 'superadmin' ? 9 : 8;
        tbody.innerHTML = `<tr><td colspan="${colSpanCount}" class="text-center py-6 text-slate-400">Tidak ada data guru yang cocok atau database kosong.</td></tr>`;
      } else {
        paged.forEach((g, idx) => {
          const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);
          const metrics = getGuruEvaluationMetrics(g);
          const tr = document.createElement('tr');
          tr.className = 'hover:bg-slate-50 transition';

          const isChecked = selectedGuruIds.has(g.id);
          const checkboxHtml = currentRole === 'superadmin' ? `
            <td class="py-3 px-3 text-center no-print">
              <input type="checkbox" onchange="toggleSelectSingleGuru(${g.id}, this.checked)" ${isChecked ? 'checked' : ''} class="guru-item-checkbox rounded text-rose-600 focus:ring-rose-500 cursor-pointer">
            </td>
          ` : '';

          // Menu Edit tersedia untuk Superadmin dan Supervisor
          const canEdit = (currentRole === 'superadmin' || currentRole === 'supervisor');
          const editBtnHtml = canEdit ? `
            <button onclick="openEditGuruModal(${g.id})" title="Edit Data Guru" class="p-1.5 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-700 transition">
              <i class="fa-solid fa-pen-to-square"></i>
            </button>
          ` : '';

          const deleteBtnHtml = currentRole === 'superadmin' ? `
            <button onclick="openDeleteGuruModal(${g.id}, '${g.nama.replace(/'/g, "\\'")}')" title="Hapus Guru (Superadmin)" class="p-1.5 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-600 transition">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          ` : '';

          tr.innerHTML = `
            ${checkboxHtml}
            <td class="py-3 px-4 font-medium text-slate-500 whitespace-nowrap">${startIdx + idx + 1}</td>
            <td class="py-3 px-4 whitespace-nowrap">
              <span class="font-bold text-slate-800 block">${g.nama}</span>
              <span class="text-[10px] text-slate-400">NIP. ${g.nip}</span>
            </td>
            <td class="py-3 px-4 text-slate-700 whitespace-nowrap">${g.mapel}</td>
            <td class="py-3 px-4 text-slate-700 whitespace-nowrap">${g.kelas}</td>
            <td class="py-3 px-4 text-slate-600 text-[11px] whitespace-nowrap">${spv ? spv.nama.split('(')[0].trim() : '-'}</td>
            <td class="py-3 px-4 text-center whitespace-nowrap">
              <span class="inline-block whitespace-nowrap px-2.5 py-1 rounded-full text-[10px] font-bold ${g.status === 'Selesai' ? 'bg-emerald-100 text-emerald-800' : (g.status === 'Tindak Lanjut' ? 'bg-amber-100 text-amber-800' : 'bg-rose-100 text-rose-800')}">
                ${g.status}
              </span>
            </td>
            <td class="py-3 px-4 text-center whitespace-nowrap">
              <span class="inline-block whitespace-nowrap px-2.5 py-1 rounded-full text-[10px] font-bold ${metrics.badgeColor}">
                ${metrics.predikat}
              </span>
            </td>
            <td class="py-3 px-4 text-center no-print whitespace-nowrap">
              <div class="flex items-center justify-center space-x-1">
                ${editBtnHtml}
                <button onclick="pilihDanNavigasi(${g.id}, 'pra')" title="Pra-Observasi (Telaah Modul)" class="p-1.5 rounded-lg bg-indigo-50 hover:bg-indigo-100 text-indigo-600"><i class="fa-solid fa-file-signature"></i></button>
                <button onclick="pilihDanNavigasi(${g.id}, 'observasi')" title="Observasi Kelas" class="p-1.5 rounded-lg bg-blue-50 hover:bg-blue-100 text-blue-600"><i class="fa-solid fa-clipboard-check"></i></button>
                <button onclick="pilihDanNavigasi(${g.id}, 'laporan')" title="Lihat Laporan" class="p-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700"><i class="fa-solid fa-print"></i></button>
                ${deleteBtnHtml}
              </div>
            </td>
          `;
          tbody.appendChild(tr);
        });
      }

      updateMasterCheckboxState(paged);
      updateBulkActionBar();

      const pagInfo = document.getElementById('pagination-info');
      if (pagInfo) pagInfo.innerText = `Menampilkan ${totalItems === 0 ? 0 : startIdx + 1}-${Math.min(startIdx + guruPageSize, totalItems)} dari ${totalItems} guru`;

      const pagControls = document.getElementById('pagination-controls');
      if (pagControls) {
        pagControls.innerHTML = `
          <button onclick="changeGuruPage(${guruCurrentPage - 1})" ${guruCurrentPage === 1 ? 'disabled class="opacity-40 cursor-not-allowed"' : 'class="hover:bg-slate-200"'} class="px-2.5 py-1 rounded border border-slate-300">Prev</button>
          <span class="px-2 font-bold text-slate-700">${guruCurrentPage} / ${totalPages}</span>
          <button onclick="changeGuruPage(${guruCurrentPage + 1})" ${guruCurrentPage === totalPages ? 'disabled class="opacity-40 cursor-not-allowed"' : 'class="hover:bg-slate-200"'} class="px-2.5 py-1 rounded border border-slate-300">Next</button>
        `;
      }
    }

    function filterGuruTable() {
      guruCurrentPage = 1;
      renderGuruTable();
    }

    function changeGuruPage(newPage) {
      const searchVal = (document.getElementById('guru-search')?.value || '').toLowerCase();
      const filterMapel = document.getElementById('guru-filter-mapel')?.value || '';
      const filterStatus = document.getElementById('guru-filter-status')?.value || '';

      const filtered = guruDatabase.filter(g => {
        const matchSearch = g.nama.toLowerCase().includes(searchVal) || g.nip.includes(searchVal);
        const matchMapel = !filterMapel || g.mapel === filterMapel;
        const matchStatus = !filterStatus || g.status === filterStatus;
        return matchSearch && matchMapel && matchStatus;
      });

      const totalPages = Math.ceil(filtered.length / guruPageSize) || 1;
      if (newPage >= 1 && newPage <= totalPages) {
        guruCurrentPage = newPage;
        renderGuruTable();
      }
    }

    function pilihDanNavigasi(id, targetView) {
      syncSelectedGuru(id);
      navigateTo(targetView);
    }

    function updateDashboardKPI() {
      const list = getSupervisorTeachers();
      const total = list.length;
      const selesai = list.filter(g => g.status === 'Selesai').length;
      const tindak = list.filter(g => g.status === 'Tindak Lanjut').length;
      const belum = list.filter(g => g.status === 'Belum').length;

      const kpiTotal = document.getElementById('kpi-total');
      const kpiSelesai = document.getElementById('kpi-selesai');
      const kpiSelesaiPct = document.getElementById('kpi-selesai-pct');
      const kpiTindak = document.getElementById('kpi-tindak');
      const kpiBelum = document.getElementById('kpi-belum');
      const kpiLabelTotal = document.getElementById('kpi-label-total');
      const kpiSubTotal = document.getElementById('kpi-sub-total');

      if (kpiLabelTotal) kpiLabelTotal.innerText = currentRole === 'supervisor' ? 'Total Guru Binaan' : 'Total Guru';
      if (kpiSubTotal) kpiSubTotal.innerText = currentRole === 'supervisor' ? 'Guru Binaan Supervisor' : 'Terdaftar di Sistem';

      if (kpiTotal) kpiTotal.innerText = total;
      if (kpiSelesai) kpiSelesai.innerText = selesai;
      if (kpiSelesaiPct) kpiSelesaiPct.innerText = total > 0 ? Math.round((selesai / total) * 100) : 0;
      if (kpiTindak) kpiTindak.innerText = tindak;
      if (kpiBelum) kpiBelum.innerText = belum;
    }

