    function renderCharts() {
      let sb = 0, b = 0, c = 0, d = 0;
      const list = getSupervisorTeachers();
      list.forEach(g => {
        const m = getGuruEvaluationMetrics(g);
        if (m.predikat.includes('Sangat Baik')) sb++;
        else if (m.predikat.includes('Baik')) b++;
        else if (m.predikat.includes('Cukup')) c++;
        else d++;
      });

      const ctxPred = document.getElementById('chartPredikat');
      if (ctxPred) {
        if (chartPredikatInstance) chartPredikatInstance.destroy();
        chartPredikatInstance = new Chart(ctxPred, {
          type: 'doughnut',
          data: {
            labels: ['Sangat Baik (A)', 'Baik (B)', 'Cukup (C)', 'Perlu Pembinaan (D)'],
            datasets: [{
              data: [sb, b, c, d],
              backgroundColor: ['#10b981', '#3b82f6', '#f59e0b', '#ef4444'],
              borderWidth: 2,
              borderColor: '#ffffff'
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, font: { size: 10 } } } }
          }
        });
      }

      const ctxAspek = document.getElementById('chartAspek');
      if (ctxAspek) {
        if (chartAspekInstance) chartAspekInstance.destroy();

        const dynamicAspectData = ASPEK_OBSERVASI.map(aspek => {
          let totalScore = 0;
          let totalMax = 0;
          list.forEach(g => {
            if (g.obsScores && Object.keys(g.obsScores).length > 0) {
              aspek.indikator.forEach(ind => {
                if (g.obsScores[ind.id] !== undefined && Number(g.obsScores[ind.id]) > 0) {
                  totalScore += Number(g.obsScores[ind.id]);
                  totalMax += 4;
                }
              });
            }
          });
          return totalMax > 0 ? Math.round((totalScore / totalMax) * 100) : 0;
        });

        chartAspekInstance = new Chart(ctxAspek, {
          type: 'bar',
          data: {
            labels: ['Pendahuluan', 'Penguasaan', 'Strategi/Dif.', 'Media TIK', 'Manajemen', 'Asesmen', 'Penutup'],
            datasets: [{
              label: 'Capaian Rata-rata (%)',
              data: dynamicAspectData,
              backgroundColor: '#6366f1',
              borderRadius: 6
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
              y: {
                min: 0,
                max: 100,
                ticks: {
                  callback: function(value) { return value + '%'; },
                  font: { size: 10 }
                }
              },
              x: { ticks: { font: { size: 10 } } }
            },
            plugins: {
              legend: { display: false },
              tooltip: {
                callbacks: {
                  label: function(context) { return ` Capaian Rata-rata: ${context.parsed.y}%`; }
                }
              }
            }
          }
        });
      }
    }

