    function openImportExcelModal() {
      importedTempTeachers = [];
      const infoEl = document.getElementById('excel-preview-info');
      if (infoEl) infoEl.classList.add('hidden');
      const btnSave = document.getElementById('btn-save-excel');
      if (btnSave) btnSave.disabled = true;
      document.getElementById('modal-import-excel').classList.remove('hidden');
    }

    function closeImportExcelModal() {
      document.getElementById('modal-import-excel').classList.add('hidden');
    }

    function handleExcelFileUpload(evt) {
      const file = evt.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const data = new Uint8Array(e.target.result);
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
          const jsonData = XLSX.utils.sheet_to_json(firstSheet);

          if (!jsonData || jsonData.length === 0) {
            showToast('File Excel kosong atau format tidak sesuai!', true);
            return;
          }

          importedTempTeachers = jsonData.map((row, idx) => {
            const nama = row['Nama Lengkap'] || row['Nama'] || row['nama'] || `Guru Baru ${idx + 1}`;
            const nip = String(row['NIP'] || row['nip'] || `19850000000000000${idx}`).trim();
            const mapel = row['Mata Pelajaran'] || row['Mapel'] || row['mapel'] || 'Umum';
            const kelas = row['Kelas'] || row['kelas'] || 'Kelas 7';
            return { nama, nip, mapel, kelas };
          });

          const previewEl = document.getElementById('excel-preview-info');
          if (previewEl) {
            previewEl.classList.remove('hidden');
            previewEl.innerHTML = `
              <p class="font-bold text-slate-800">File berhasil dibaca!</p>
              <p class="text-slate-600 mt-1">Ditemukan <strong>${importedTempTeachers.length}</strong> data guru siap diimpor ke sistem.</p>
            `;
          }
          document.getElementById('btn-save-excel').disabled = false;
        } catch (err) {
          showToast('Gagal memproses file spreadsheet.', true);
        }
      };
      reader.readAsArrayBuffer(file);
    }

    function confirmImportExcel() {
      if (importedTempTeachers.length === 0) return;

      const startMaxId = guruDatabase.length > 0 ? Math.max(...guruDatabase.map(g => g.id)) : 0;
      let firstNewTeacherId = null;

      importedTempTeachers.forEach((item, idx) => {
        const newId = startMaxId + idx + 1;
        if (idx === 0) firstNewTeacherId = newId;
        guruDatabase.push({
          id: newId,
          nama: item.nama,
          nip: item.nip,
          mapel: item.mapel,
          kelas: item.kelas,
          password: item.nip,
          supervisorId: (idx % 6) + 1,
          targetPerilaku: (item.mapel === 'BK') ? 'Perhatian dan Kepedulian' : 'Instruksi Pembelajaran',
          status: 'Belum',
          materiTopik: '',
          tujuanPembelajaran: '',
          tanggalTelaah: new Date().toISOString().slice(0, 10),
          rppScores: {},
          bkScores: {},
          bkDlScores: {},
          bkDlNotes: {},
          obsScores: {},
          obsNotes: {},
          deepLearning: { mindful: 0, meaningful: 0, joyful: 0, memahami: 0, mengaplikasi: 0, merefleksi: 0 },
          praFeedback: {},
          catatanPra: '',
          catatanFakta: '',
          coaching: { tujuan: '', identifikasi: '', rencana: '', tanggungJawab: '' }
        });
      });

      closeImportExcelModal();
      populateDropdowns();
      filterGuruTable();
      updateDashboardKPI();
      renderRekapTable();

      if (firstNewTeacherId) {
        syncSelectedGuru(firstNewTeacherId);
      }

      saveDataToLocalStorage();
      showToast(`Berhasil menambahkan ${importedTempTeachers.length} guru dari Excel!`);

      // Sync ke MySQL Server API
      apiCall('import_excel_guru', { teachers: importedTempTeachers }).then(res => {
        if (res && res.success && isServerOnline) {
          showToast(res.message || 'Data impor tersimpan di database MySQL!');
        }
      }).catch(() => {});
    }

    function exportToExcel() {
      const dataToExport = getRekapFilteredTeachers();

      const exportRows = dataToExport.map((g, idx) => {
        const m = getGuruEvaluationMetrics(g);
        const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);
        return {
          "No": idx + 1,
          "Nama Guru": g.nama,
          "NIP": g.nip,
          "Mata Pelajaran": g.mapel,
          "Kelas": g.kelas,
          "Supervisor": spv ? spv.nama : '-',
          "Status": g.status,
          "Skor Dokumen (%)": m.rppPct,
          "Skor Observasi (%)": m.obsPct,
          "Skor Akhir (%)": m.finalScore,
          "Predikat Kinerja": m.predikat
        };
      });

      const ws = XLSX.utils.json_to_sheet(exportRows);
      const wb = XLSX.utils.book_new();
      const sheetName = currentRole === 'guru' ? "Laporan_Supervisi_Guru" : "Rekap_Supervisi";
      let fileName = `Rekap_Supervisi_${currentRole}_${new Date().toISOString().slice(0, 10)}.xlsx`;

      if (currentRole === 'guru' && currentLoggedInUser) {
        fileName = `Laporan_Supervisi_${currentLoggedInUser.nip}_${new Date().toISOString().slice(0, 10)}.xlsx`;
      } else if (currentRole === 'supervisor' && currentLoggedInUser) {
        fileName = `Rekap_Binaan_${currentLoggedInUser.nama.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().slice(0, 10)}.xlsx`;
      }

      XLSX.utils.book_append_sheet(wb, ws, sheetName);
      XLSX.writeFile(wb, fileName);
      showToast('Data berhasil diekspor ke Excel!');
    }

    function exportDatabaseGuruToExcel() {
      if (!guruDatabase || !guruDatabase.length) {
        showToast('Tidak ada data guru untuk diekspor!', 'error');
