    function populateUserAccountsTable(customList) {
      let list = customList;
      if (!list) {
        const q = (document.getElementById('user-search-input')?.value || '').toLowerCase();
        const roleFilter = document.getElementById('user-filter-role')?.value || '';
        const spvFilter = document.getElementById('user-filter-spv')?.value || '';

        list = guruDatabase || [];
        if (q || roleFilter || spvFilter) {
          list = guruDatabase.filter(g => {
            const matchSearch = (g.nama || '').toLowerCase().includes(q) || (g.nip || '').toLowerCase().includes(q) || (g.mapel || '').toLowerCase().includes(q);
            let matchRole = true;
            if (roleFilter === 'superadmin') matchRole = !!g.is_superadmin;
            else if (roleFilter === 'supervisor') matchRole = !!g.is_supervisor;
            else if (roleFilter === 'guru') matchRole = !g.is_supervisor && !g.is_superadmin;
            let matchSpv = true;
            if (spvFilter !== '') matchSpv = (String(g.supervisorId) === String(spvFilter));
            return matchSearch && matchRole && matchSpv;
          });
        }
      }

      // Clone Kop Surat if target is empty
      const targetKop = document.getElementById('kop-user-accounts-target');
      if (targetKop) {
        const srcKop = document.querySelector('#printable-all-reports .kop-surat-container') || document.querySelector('#printable-report .kop-surat-container');
        if (srcKop) {
          targetKop.innerHTML = srcKop.outerHTML;
        }
      }

      // Update Period & Identity
      const periodeEl = document.getElementById('user-accounts-doc-periode');
      if (periodeEl) {
        periodeEl.textContent = `${appSettings.sekolah || 'SMP NEGERI 24 MALANG'} • TAHUN AJARAN ${appSettings.tahunAjaran || '2026/2027'} (${appSettings.semester || 'Semester Ganjil'})`;
      }

      const dateEl = document.getElementById('user-accounts-doc-date');
      if (dateEl) {
        dateEl.textContent = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
      }

      const ksNama = (appSettings.kepalaSekolah && typeof appSettings.kepalaSekolah === 'object')
        ? (appSettings.kepalaSekolah.nama || 'Drs. Teguh Edy Purwanta')
        : (appSettings.kepalaSekolah || 'Drs. Teguh Edy Purwanta');
      const ksNip = (appSettings.kepalaSekolah && typeof appSettings.kepalaSekolah === 'object')
        ? (appSettings.kepalaSekolah.nip || '196710202000031006')
        : (appSettings.nipKepalaSekolah || '196710202000031006');

      const ksNamaEl = document.getElementById('user-accounts-ks-nama');
      if (ksNamaEl) ksNamaEl.textContent = ksNama;

      const ksNipEl = document.getElementById('user-accounts-ks-nip');
      if (ksNipEl) ksNipEl.textContent = 'NIP. ' + ksNip;

      // Populate Table Body
      const tbody = document.getElementById('user-accounts-tbody');
      if (tbody) {
        tbody.innerHTML = list.map((g, idx) => {
          return `
            <tr class="border-b border-slate-200" style="page-break-inside: avoid; break-inside: avoid;">
              <td class="border border-slate-300 py-1 px-2 text-center text-[10px] text-slate-500">${idx + 1}</td>
              <td class="border border-slate-300 py-1 px-2.5 font-bold text-slate-800 text-[10px]">
                <div class="leading-tight">${g.nama}</div>
                <div class="text-[9px] font-mono font-normal text-slate-500 leading-tight">NIP: ${g.nip || '-'}</div>
              </td>
              <td class="border border-slate-300 py-1 px-2.5 text-slate-700 text-[10px] leading-tight">
                ${g.mapel || '-'} ${g.kelas ? '<span class="text-slate-400 font-medium">(' + g.kelas + ')</span>' : ''}
              </td>
              <td class="border border-slate-300 py-1 px-2.5 font-mono font-bold text-slate-900 text-[10.5px] tracking-wide">
                ${g.nip}
              </td>
              <td class="border border-slate-300 py-1 px-2 text-center font-mono font-bold text-emerald-700 text-[10.5px] bg-slate-50 tracking-wider">
                ${g.password || '123456'}
              </td>
            </tr>
          `;
        }).join('');
      }

      return list;
    }

    function downloadUserAccountsPDF() {
      if (typeof html2pdf === 'undefined') {
        showToast('Pustaka PDF sedang dimuat, silakan coba sesaat lagi...', 'error');
        return;
      }
      if (!guruDatabase || !guruDatabase.length) {
        showToast('Tidak ada data akun guru!', 'error');
        return;
      }

      showToast('Sedang membuat berkas PDF Data Akun Guru... Mohon tunggu.');

      const list = populateUserAccountsTable();
      if (!list || !list.length) {
        showToast('Tidak ada akun guru yang sesuai dengan filter pencarian!', 'error');
        return;
      }

      const el = document.getElementById('printable-user-accounts');
      if (!el) {
        showToast('Elemen cetak akun tidak ditemukan!', 'error');
        return;
      }

      const wasHidden = el.classList.contains('hidden');
      el.classList.remove('hidden');

      // Reset outer padding and margin during canvas capture to prevent spilling an extra trailing page
      const origPadding = el.style.padding;
      const origMargin = el.style.margin;
      el.style.padding = '0px';
      el.style.margin = '0px auto';

      const filename = `Data_Akun_Login_Guru_SMPN24_${new Date().toISOString().slice(0, 10)}.pdf`;

      const opt = {
        margin: [6, 8, 6, 8],
        filename: filename,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, logging: false },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };

      html2pdf().set(opt).from(el).save().then(() => {
        el.style.padding = origPadding;
        el.style.margin = origMargin;
        if (wasHidden) el.classList.add('hidden');
        showToast('Berkas PDF Data Akun Guru berhasil diunduh!');
      }).catch(err => {
        el.style.padding = origPadding;
        el.style.margin = origMargin;
        if (wasHidden) el.classList.add('hidden');
        console.error(err);
        showToast('Gagal membuat PDF otomatis. Silakan gunakan tombol Cetak Akun.', 'error');
      });
    }

    function printUserAccounts() {
      if (!guruDatabase || !guruDatabase.length) {
        showToast('Tidak ada data akun guru!', 'error');
        return;
      }

      const list = populateUserAccountsTable();
      if (!list || !list.length) {
        showToast('Tidak ada akun guru yang sesuai dengan filter pencarian!', 'error');
        return;
      }

      const el = document.getElementById('printable-user-accounts');
      if (!el) return;

      const wasHidden = el.classList.contains('hidden');
      el.classList.remove('hidden');

      window.print();

      setTimeout(() => {
        if (wasHidden) el.classList.add('hidden');
      }, 1000);
    }

    function exportUserAccountsExcel() {
      if (!guruDatabase || !guruDatabase.length) {
        showToast('Tidak ada data akun guru!', 'error');
        return;
      }
      const exportRows = guruDatabase.map((g, idx) => {
        let roleText = 'Guru Biasa';
        if (g.is_superadmin) roleText = 'Super Admin';
        else if (g.is_supervisor) roleText = 'Supervisor';

        const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);

        return {
          "No": idx + 1,
          "Nama Lengkap": g.nama,
          "Mata Pelajaran": g.mapel,
          "Kelas": g.kelas,
          "Hak Akses / Peran": roleText,
          "Username (NIP)": g.nip,
          "Password (Kata Sandi)": g.password || '123456',
          "Supervisor Penilai": spv ? spv.nama : '-'
        };
      });

      const ws = XLSX.utils.json_to_sheet(exportRows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Data_Akun_Guru");
      const filename = `Data_Akun_Guru_SMPN24_${new Date().toISOString().slice(0, 10)}.xlsx`;
      XLSX.writeFile(wb, filename);
      showToast('Data akun guru berhasil diekspor ke Excel (.xlsx)!');
    }

    function openAddGuruModal() {
      document.getElementById('add-guru-nama').value = '';
      document.getElementById('add-guru-nip').value = '';
      document.getElementById('add-guru-mapel').value = '';
      document.getElementById('add-guru-kelas').value = '';
      document.getElementById('modal-add-guru').classList.remove('hidden');
    }

    function closeAddGuruModal() {
      document.getElementById('modal-add-guru').classList.add('hidden');
    }

    function submitAddGuru() {
      const nama = document.getElementById('add-guru-nama').value.trim();
      const nip = document.getElementById('add-guru-nip').value.trim();
      const mapel = document.getElementById('add-guru-mapel').value.trim();
      const kelas = document.getElementById('add-guru-kelas').value.trim();

      if (!nama || !nip) {
        showToast('Nama Lengkap dan NIP wajib diisi!', true);
        return;
      }

      const newId = (guruDatabase.length > 0 ? Math.max(...guruDatabase.map(g => g.id)) : 0) + 1;
      const isBk = (mapel.toUpperCase() === 'BK' || mapel.toUpperCase() === 'BIMBINGAN KONSELING');
      const finalMapel = isBk ? 'BK' : (mapel || 'Umum');

      const newGuru = {
        id: newId,
        nama: nama,
        nip: nip,
        mapel: finalMapel,
        kelas: kelas || 'Kelas 7',
        password: nip,
        supervisorId: 1,
        targetPerilaku: isBk ? 'Perhatian dan Kepedulian' : 'Instruksi Pembelajaran',
        status: 'Belum',
        materiTopik: '',
        tujuanPembelajaran: '',
        tanggalTelaah: new Date().toISOString().slice(0, 10),
        rppScores: {},
        bkScores: {},
        bkDlScores: {},
        bkDlNotes: {},
        obsScores: {},
        obsNotes: {},
        deepLearning: { mindful: 0, meaningful: 0, joyful: 0, memahami: 0, mengaplikasi: 0, merefleksi: 0 },
        praFeedback: {},
        catatanPra: '',
        catatanFakta: '',
        coaching: { tujuan: '', identifikasi: '', rencana: '', tanggungJawab: '' }
      };
      guruDatabase.push(newGuru);

      closeAddGuruModal();
      populateDropdowns();
      filterGuruTable();
      updateDashboardKPI();
      renderRekapTable();

      syncSelectedGuru(newId);
      saveDataToLocalStorage();
      showToast(`Guru ${nama} berhasil ditambahkan!`);

      // Sync ke MySQL Server API
      apiCall('add_guru', {
        nama: nama,
        nip: nip,
        mapel: finalMapel,
        kelas: kelas || 'Kelas 7',
        supervisorId: 1,
        targetPerilaku: newGuru.targetPerilaku
      }).then(res => {
        if (res && res.newId) {
          newGuru.id = res.newId;
          syncSelectedGuru(res.newId);
        }
        if (res && res.message && isServerOnline) {
          showToast(res.message);
        }
      }).catch(() => {});
    }

    // Modal Edit Guru Logic
    function openEditGuruModal(id) {
      const guru = guruDatabase.find(g => g.id === id);
      if (!guru) return;

      document.getElementById('edit-guru-id').value = guru.id;
      document.getElementById('edit-guru-nama').value = guru.nama;
      document.getElementById('edit-guru-nip').value = guru.nip;
      document.getElementById('edit-guru-mapel').value = guru.mapel;
      document.getElementById('edit-guru-kelas').value = guru.kelas;

      const spvSel = document.getElementById('edit-guru-supervisor');
      if (spvSel) {
        spvSel.innerHTML = appSettings.supervisors.map(s => `
          <option value="${s.id}" ${guru.supervisorId === s.id ? 'selected' : ''}>${s.nama}</option>
        `).join('');
      }

      const targetSel = document.getElementById('edit-guru-target');
      if (targetSel) {
        targetSel.value = guru.targetPerilaku || 'Instruksi Pembelajaran';
      }

      document.getElementById('modal-edit-guru').classList.remove('hidden');
    }

    function closeEditGuruModal() {
      document.getElementById('modal-edit-guru').classList.add('hidden');
    }

    function submitEditGuru() {
      const id = parseInt(document.getElementById('edit-guru-id').value);
      const guru = guruDatabase.find(g => g.id === id);
      if (!guru) return;

      const nama = document.getElementById('edit-guru-nama').value.trim();
      const nip = document.getElementById('edit-guru-nip').value.trim();
      const mapel = document.getElementById('edit-guru-mapel').value.trim();
      const kelas = document.getElementById('edit-guru-kelas').value.trim();
      const spvId = parseInt(document.getElementById('edit-guru-supervisor').value) || 1;
      const target = document.getElementById('edit-guru-target').value;

      if (!nama || !nip) {
        showToast('Nama Lengkap dan NIP wajib diisi!', true);
        return;
      }

      const isBk = (mapel.toUpperCase() === 'BK' || mapel.toUpperCase() === 'BIMBINGAN KONSELING');
      guru.nama = nama;
      guru.nip = nip;
      guru.mapel = isBk ? 'BK' : (mapel || 'Umum');
      guru.kelas = kelas || 'Kelas 7';
      guru.supervisorId = spvId;
      guru.targetPerilaku = target;

      closeEditGuruModal();
      populateDropdowns();
      filterGuruTable();
      updateDashboardKPI();
      renderDashboardTable();
      renderRekapTable();

      if (selectedGuruId === id) {
        syncSelectedGuru(id);
      }

      saveDataToLocalStorage();
      showToast(`Data guru ${nama} berhasil diperbarui!`);

      // Sync ke MySQL Server API
      apiCall('edit_guru', {
        id: guru.id,
        nama: guru.nama,
        nip: guru.nip,
        mapel: guru.mapel,
        kelas: guru.kelas,
        supervisorId: guru.supervisorId,
        targetPerilaku: guru.targetPerilaku
      }).then(res => {
        if (res && res.message && isServerOnline) {
          showToast(res.message);
        }
      }).catch(() => {});
    }

