    };

    function renderSupervisorInputs() {
      const grid = document.getElementById('supervisors-input-grid');
      if (!grid) return;
      grid.innerHTML = '';

      appSettings.supervisors.forEach(spv => {
        const duty = SUPERVISOR_DUTIES[spv.id] || 'Guru Binaan Terkait';
        const teacherCount = guruDatabase.filter(g => g.supervisorId === spv.id).length;
        const div = document.createElement('div');
        div.className = 'bg-slate-50 p-3.5 rounded-xl border border-slate-200 space-y-2';
        div.innerHTML = `
          <div class="flex items-center justify-between">
            <span class="font-bold text-slate-800 text-xs flex items-center space-x-1.5">
              <span class="w-5 h-5 rounded-full bg-indigo-100 text-indigo-700 flex items-center justify-center font-bold text-[10px]">${spv.id}</span>
              <span>Supervisor ${spv.id}</span>
            </span>
            <span class="px-2 py-0.5 rounded text-[10px] font-semibold bg-indigo-50 text-indigo-700 border border-indigo-200">${teacherCount} Guru Terbina</span>
          </div>
          <div class="grid grid-cols-2 gap-2 text-xs">
            <div>
              <label class="block text-[10px] font-semibold text-slate-500 mb-0.5">Nama & Gelar</label>
              <input type="text" id="spv-nama-${spv.id}" value="${spv.nama}" placeholder="Nama & Gelar" class="w-full p-2 rounded-lg border border-slate-300 text-xs font-medium">
            </div>
            <div>
              <label class="block text-[10px] font-semibold text-slate-500 mb-0.5">NIP</label>
              <input type="text" id="spv-nip-${spv.id}" value="${spv.nip}" placeholder="NIP" class="w-full p-2 rounded-lg border border-slate-300 text-xs font-mono">
            </div>
          </div>
          <div class="p-2 bg-white rounded-lg border border-slate-200 text-[11px] text-slate-600 flex items-start space-x-1.5">
            <i class="fa-solid fa-graduation-cap text-indigo-500 mt-0.5 flex-shrink-0"></i>
            <div>
              <span class="font-semibold text-slate-700">Sasaran Supervisi:</span>
              <p class="text-slate-500 text-[10px] leading-relaxed mt-0.5">${duty}</p>
