    function saveSettings() {
      appSettings.sekolah = document.getElementById('set-sekolah').value;
      appSettings.periode = document.getElementById('set-periode').value;
      appSettings.kepalaSekolah.nama = document.getElementById('set-ks-nama').value;
      appSettings.kepalaSekolah.nip = document.getElementById('set-ks-nip').value;
      if (!appSettings.pengawasSekolah) appSettings.pengawasSekolah = { nama: 'Drs. Mochamad Solikin', nip: '196808061998021005' };
      const pNamaEl = document.getElementById('set-pengawas-nama');
      const pNipEl = document.getElementById('set-pengawas-nip');
      if (pNamaEl) appSettings.pengawasSekolah.nama = pNamaEl.value;
      if (pNipEl) appSettings.pengawasSekolah.nip = pNipEl.value;

      appSettings.supervisors.forEach(spv => {
        const nEl = document.getElementById(`spv-nama-${spv.id}`);
        const nipEl = document.getElementById(`spv-nip-${spv.id}`);
        if (nEl) spv.nama = nEl.value;
        if (nipEl) spv.nip = nipEl.value;
      });

      const schoolNameSide = document.getElementById('sidebar-sekolah-nama');
      if (schoolNameSide) schoolNameSide.innerText = appSettings.sekolah;

      // Sinkronisasi otomatis semester & tahun ajaran di menu pra-observasi dan kop cetak
      const praPeriodeEl = document.getElementById('pra-id-periode');
      if (praPeriodeEl) praPeriodeEl.value = appSettings.periode;

      const kopPeriode = document.getElementById('kop-periode');
      if (kopPeriode) kopPeriode.innerText = appSettings.periode;

      const kopAllPeriode = document.getElementById('kop-all-periode');
      if (kopAllPeriode) kopAllPeriode.innerText = appSettings.periode;

      const kopAllSekolah = document.getElementById('kop-all-sekolah');
      if (kopAllSekolah) kopAllSekolah.innerText = appSettings.sekolah;

      saveDataToLocalStorage();
      showToast('Pengaturan sistem berhasil disimpan dan disinkronkan!');

      // Sync ke MySQL Server API
      apiCall('save_settings', appSettings).then(res => {
        if (res && res.message && isServerOnline) {
          showToast(res.message);
        }
      }).catch(() => {});
    }

    // Fungsi Cetak Laporan Keseluruhan
    function printLaporanKeseluruhan() {
      const allReportDiv = document.getElementById('printable-all-reports');
      const singleReportDiv = document.getElementById('printable-report');
      const tbody = document.getElementById('all-report-tbody');

      if (!allReportDiv || !tbody) return;

      const list = getRekapFilteredTeachers();
      if (list.length === 0) {
        showToast('Tidak ada data guru untuk dicetak.', true);
        return;
      }

      // Update Header Kop
      document.getElementById('kop-all-sekolah').innerText = appSettings.sekolah;
      document.getElementById('kop-all-periode').innerText = appSettings.periode;
      document.getElementById('all-report-date').innerText = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
      document.getElementById('all-report-ks-ttd').innerText = appSettings.kepalaSekolah.nama;
      document.getElementById('all-report-ks-nip').innerText = `NIP. ${appSettings.kepalaSekolah.nip}`;

      const subtitleEl = document.getElementById('all-report-subtitle');
      if (currentRole === 'supervisor') {
        const spvName = (currentLoggedInUser && currentLoggedInUser.nama) ? currentLoggedInUser.nama : 'Supervisor';
        if (subtitleEl) subtitleEl.innerText = `Rekapitulasi Khusus Guru Binaan: ${spvName}`;
        document.getElementById('all-report-spv-ttd').innerText = spvName.split('(')[0];
      } else {
        if (subtitleEl) subtitleEl.innerText = `Rekapitulasi Keseluruhan Guru (${rekapFilterMode.toUpperCase()}) - Total: ${list.length} Guru`;
        document.getElementById('all-report-spv-ttd').innerText = 'Koordinator Supervisor Sekolah';
      }

      // Render Rows
      tbody.innerHTML = list.map((g, idx) => {
        const m = getGuruEvaluationMetrics(g);
        const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);
        return `
          <tr class="text-[11px]">
            <td class="border border-slate-300 p-1.5 text-center">${idx + 1}</td>
            <td class="border border-slate-300 p-1.5">
              <span class="font-bold block">${g.nama}</span>
              <span class="text-[10px] text-slate-500">NIP. ${g.nip}</span>
            </td>
            <td class="border border-slate-300 p-1.5 text-center">${g.mapel}</td>
            <td class="border border-slate-300 p-1.5 text-center">${g.kelas}</td>
            <td class="border border-slate-300 p-1.5 text-center text-[10px]">${spv ? spv.nama.split('(')[0] : '-'}</td>
            <td class="border border-slate-300 p-1.5 text-center font-semibold text-indigo-700">${m.rppPct}%</td>
            <td class="border border-slate-300 p-1.5 text-center font-semibold text-blue-700">${m.obsPct}%</td>
            <td class="border border-slate-300 p-1.5 text-center font-bold text-emerald-700">${m.finalScore}%</td>
            <td class="border border-slate-300 p-1.5 text-center font-semibold">${m.predikat}</td>
            <td class="border border-slate-300 p-1.5 text-center text-[10px]">${g.status}</td>
          </tr>
        `;
      }).join('');

      // Sembunyikan laporan tunggal, tampilkan laporan keseluruhan lalu cetak
      if (singleReportDiv) singleReportDiv.classList.add('hidden');
      allReportDiv.classList.remove('hidden');

      setTimeout(() => {
        window.print();
        // Kembalikan tampilan setelah dialog cetak ditutup
        setTimeout(() => {
          allReportDiv.classList.add('hidden');
          if (singleReportDiv) singleReportDiv.classList.remove('hidden');
        }, 800);
      }, 200);
    }

    function toggleSelectAllGuru(isChecked) {
      if (isChecked) {
        guruDatabase.forEach(g => selectedGuruIds.add(g.id));
      } else {
        selectedGuruIds.clear();
      }
      renderGuruTable();
    }

    function toggleSelectSingleGuru(id, isChecked) {
      if (isChecked) {
        selectedGuruIds.add(id);
      } else {
        selectedGuruIds.delete(id);
      }
      updateBulkActionBar();
      const pagedCheckboxes = document.querySelectorAll('.guru-item-checkbox');
      const allChecked = pagedCheckboxes.length > 0 && Array.from(pagedCheckboxes).every(cb => cb.checked);
      const masterCheck = document.getElementById('check-all-guru');
      if (masterCheck) masterCheck.checked = allChecked;
    }

    function updateMasterCheckboxState(currentPagedTeachers) {
      const masterCheck = document.getElementById('check-all-guru');
      if (!masterCheck) return;
      if (currentPagedTeachers.length === 0) {
        masterCheck.checked = false;
        return;
      }
      const allPageSelected = currentPagedTeachers.every(g => selectedGuruIds.has(g.id));
      masterCheck.checked = allPageSelected;
    }

    function deselectAllGuru() {
      selectedGuruIds.clear();
      const masterCheck = document.getElementById('check-all-guru');
      if (masterCheck) masterCheck.checked = false;
      updateBulkActionBar();
      document.querySelectorAll('.guru-item-checkbox').forEach(cb => cb.checked = false);
    }

    function updateBulkActionBar() {
      const bar = document.getElementById('bulk-action-bar');
      const countEl = document.getElementById('bulk-selected-count');
      if (!bar) return;

      if (currentRole === 'superadmin' && selectedGuruIds.size > 0) {
        bar.classList.remove('hidden');
        if (countEl) countEl.innerText = selectedGuruIds.size;
      } else {
        bar.classList.add('hidden');
      }
    }

    function openDeleteSelectedGuruModal() {
      if (selectedGuruIds.size === 0) return;
      const countEl = document.getElementById('modal-hapus-count');
      if (countEl) countEl.innerText = selectedGuruIds.size;
      document.getElementById('modal-hapus-terpilih-guru').classList.remove('hidden');
    }

