      document.getElementById('modal-hapus-terpilih-guru').classList.add('hidden');
    }

    function confirmDeleteSelectedGuru() {
      const count = selectedGuruIds.size;
      const idsToDelete = Array.from(selectedGuruIds);
      guruDatabase = guruDatabase.filter(g => !selectedGuruIds.has(g.id));
      closeDeleteSelectedGuruModal();
      deselectAllGuru();
      populateDropdowns();
      renderGuruTable();
      updateDashboardKPI();
      renderDashboardTable();
      renderCharts();
      renderRekapTable();

      if (!guruDatabase.some(g => g.id === selectedGuruId)) {
        if (guruDatabase.length > 0) {
          syncSelectedGuru(guruDatabase[0].id);
        } else {
          selectedGuruId = null;
          document.getElementById('side-nama').innerText = 'Database Kosong';
          document.getElementById('side-mapel').innerText = '-';
        }
      }

      saveDataToLocalStorage();
      showToast(`Berhasil menghapus ${count} guru terpilih.`);

      // Sync ke MySQL Server API
      apiCall('delete_selected_guru', { ids: idsToDelete }).catch(() => {});
    }

    function openDeleteGuruModal(id, nama) {
      guruIdToDelete = id;
      const el = document.getElementById('hapus-guru-nama-konfirm');
      if (el) el.innerHTML = `Apakah Anda yakin ingin menghapus <strong>${nama}</strong> dari database?`;
