    }

    function confirmDeleteSingleGuru() {
      if (!guruIdToDelete) return;
      const idToDelete = guruIdToDelete;
      const idx = guruDatabase.findIndex(g => g.id === idToDelete);
      if (idx !== -1) {
        const deletedNama = guruDatabase[idx].nama;
        guruDatabase.splice(idx, 1);
        closeDeleteGuruModal();
        populateDropdowns();
        renderGuruTable();
        updateDashboardKPI();
        renderCharts();
        renderRekapTable();

        if (selectedGuruId === idToDelete) {
          if (guruDatabase.length > 0) {
            syncSelectedGuru(guruDatabase[0].id);
          } else {
            selectedGuruId = null;
            document.getElementById('side-nama').innerText = 'Database Kosong';
            document.getElementById('side-mapel').innerText = '-';
          }
        }
        saveDataToLocalStorage();
        showToast(`Guru ${deletedNama} berhasil dihapus.`);

        // Sync ke MySQL Server API
        apiCall('delete_guru', { id: idToDelete }).catch(() => {});
      }
    }

