    let loginSelectedRole = 'guru';

    function setLoginRole(role) {
      loginSelectedRole = role;
      const tabGuru = document.getElementById('tab-login-guru');
      const tabSpv = document.getElementById('tab-login-spv');
      const tabAdmin = document.getElementById('tab-login-superadmin');
      const label = document.getElementById('login-user-label');

      tabGuru.className = 'flex-1 py-2 rounded-lg text-slate-500 hover:text-slate-800 transition';
      tabSpv.className = 'flex-1 py-2 rounded-lg text-slate-500 hover:text-slate-800 transition';
      if (tabAdmin) tabAdmin.className = 'flex-1 py-2 rounded-lg text-slate-500 hover:text-slate-800 transition font-bold';

      if (role === 'guru') {
        tabGuru.className = 'flex-1 py-2 rounded-lg bg-white text-indigo-700 shadow-sm transition';
        if (label) label.innerText = 'Username (NIP Guru tanpa spasi)';
      } else if (role === 'superadmin') {
        if (tabAdmin) tabAdmin.className = 'flex-1 py-2 rounded-lg bg-white text-rose-700 shadow-sm transition font-bold';
        if (label) label.innerText = 'Username Superadmin';
      } else {
        tabSpv.className = 'flex-1 py-2 rounded-lg bg-white text-indigo-700 shadow-sm transition';
        if (label) label.innerText = 'Username (NIP Supervisor / Admin)';
      }
      document.getElementById('login-error').classList.add('hidden');
    }

    async function handleLogin() {
      const u = (document.getElementById('login-username').value || '').trim();
      const p = (document.getElementById('login-password').value || '').trim();
      const errEl = document.getElementById('login-error');

      if (!u || !p) {
        errEl.innerText = 'Harap masukkan Username/NIP dan Kata Sandi!';
        errEl.classList.remove('hidden');
        return;
      }

      // 1. Coba Login ke Server MySQL REST API
      try {
        const res = await apiCall('login', { nip: u, username: u, password: p });
        if (res && res.success && res.user) {
          saveUserSession(res.user);
          selectedGuruId = res.user.id || (guruDatabase.find(g => g.nip === res.user.nip)?.id || 1);
          try { localStorage.setItem(STORAGE_KEY_SELECTED_GURU, String(selectedGuruId)); } catch(e) {}

          document.getElementById('modal-login').classList.add('hidden');
          errEl.classList.add('hidden');

          renderRoleSwitcher(res.user.available_roles || ['guru']);
          switchRole(res.user.active_role || 'guru');

          if (res.user.active_role === 'guru') {
            syncSelectedGuru(selectedGuruId);
          }
          try { localStorage.setItem(STORAGE_KEY_VIEW, 'dashboard'); } catch(e) {}
          navigateTo('dashboard');
          showToast(`Selamat datang, ${res.user.nama}!`);
          return;
        } else if (res && res.error) {
          errEl.innerText = res.error;
          errEl.classList.remove('hidden');
          return;
        }
      } catch (e) {
        console.warn('API login offline fallback', e);
      }

      // 2. Fallback Offline (jika aplikasi dijalankan langsung via file:// tanpa web server)
      if (loginSelectedRole === 'superadmin' || u.toLowerCase() === 'superadmin' || u.toLowerCase() === 'admin') {
        if (p === 'admin123' || p === 'superadmin' || p === '123456' || p === '12345678') {
          const adminObj = { nama: 'Superadmin Utama', role: 'superadmin', available_roles: ['guru', 'supervisor', 'superadmin'], active_role: 'superadmin' };
          saveUserSession(adminObj);
          document.getElementById('modal-login').classList.add('hidden');
          renderRoleSwitcher(['guru', 'supervisor', 'superadmin']);
          switchRole('superadmin');
          navigateTo('dashboard');
          showToast('Login Berhasil sebagai Superadmin (Mode Offline)!');
          return;
        }
      }

      const matchGuru = guruDatabase.find(g => g.nip === u);
      if (matchGuru) {
        if (p === matchGuru.password || p === matchGuru.nip || p === '123456' || p === '12345678') {
          const roles = ['guru'];
          if (matchGuru.is_supervisor) roles.push('supervisor');
          if (matchGuru.is_superadmin) roles.push('superadmin');
          const spvMatch = appSettings.supervisors.find(s => s.nip === matchGuru.nip);
          const guruObj = { ...matchGuru, active_spv_id: spvMatch ? spvMatch.id : null, available_roles: roles, active_role: roles[roles.length - 1] };
          saveUserSession(guruObj);
          selectedGuruId = matchGuru.id;
          try { localStorage.setItem(STORAGE_KEY_SELECTED_GURU, String(selectedGuruId)); } catch(e) {}
          document.getElementById('modal-login').classList.add('hidden');
          renderRoleSwitcher(roles);
          switchRole(currentLoggedInUser.active_role);
          if (currentLoggedInUser.active_role === 'guru') {
            syncSelectedGuru(matchGuru.id);
          }
          try { localStorage.setItem(STORAGE_KEY_VIEW, 'dashboard'); } catch(e) {}
          navigateTo('dashboard');
          showToast(`Selamat datang, ${matchGuru.nama}!`);
          return;
        } else {
          errEl.innerText = 'Kata sandi salah!';
          errEl.classList.remove('hidden');
          return;
        }
      }

      const matchSpv = appSettings.supervisors.find(s => s.nip === u);
      if (matchSpv && (p === '123456' || p === '12345678' || p === matchSpv.nip)) {
        const spvObj = { id: matchSpv.id, active_spv_id: matchSpv.id, nama: matchSpv.nama, nip: matchSpv.nip, role: 'supervisor', available_roles: ['guru', 'supervisor'], active_role: 'supervisor' };
        saveUserSession(spvObj);
        document.getElementById('modal-login').classList.add('hidden');
        renderRoleSwitcher(['guru', 'supervisor']);
        switchRole('supervisor');
        navigateTo('dashboard');
        showToast(`Login Berhasil: ${matchSpv.nama}`);
        return;
      }

      errEl.innerText = 'NIP atau kredensial guru tidak ditemukan!';
      errEl.classList.remove('hidden');
    }

    async function handleLogout() {
      await apiCall('logout').catch(() => {});
      clearUserSession();
      currentRole = 'guru';
      const container = document.getElementById('role-switch-container');
      if (container) container.classList.add('hidden');
      showLoginModal();
      showToast('Anda telah keluar dari aplikasi.');
    }

