        document.getElementById('login-username').value = sampleGuru ? sampleGuru.nip : '196808281997032008';
        document.getElementById('login-password').value = '123456';
      } else if (role === 'superadmin') {
        const adminGuru = guruDatabase.find(g => g.is_superadmin) || guruDatabase[0];
        document.getElementById('login-username').value = adminGuru ? adminGuru.nip : '196710202000031006';
        document.getElementById('login-password').value = '123456';
      } else {
        const sampleSpv = guruDatabase.find(g => g.is_supervisor && !g.is_superadmin) || appSettings.supervisors[1];
        document.getElementById('login-username').value = sampleSpv ? sampleSpv.nip : '198703282019021003';
