    function openChangePasswordModal() {
      document.getElementById('pwd-lama').value = '';
      document.getElementById('pwd-baru').value = '';
      document.getElementById('pwd-konfirmasi').value = '';
      document.getElementById('modal-ganti-password').classList.remove('hidden');
    }

    function closeChangePasswordModal() {
      document.getElementById('modal-ganti-password').classList.add('hidden');
    }

    async function submitChangePassword() {
      const lama = document.getElementById('pwd-lama').value;
      const baru = document.getElementById('pwd-baru').value;
      const konf = document.getElementById('pwd-konfirmasi').value;

      if (!baru || baru.length < 4) {
        showToast('Kata sandi baru minimal 4 karakter!', true);
        return;
      }
      if (baru !== konf) {
        showToast('Konfirmasi kata sandi tidak cocok!', true);
        return;
      }

      if (currentLoggedInUser) {
        currentLoggedInUser.password = baru;
        if (currentLoggedInUser.id) {
          const guruInDb = guruDatabase.find(g => g.id === currentLoggedInUser.id);
          if (guruInDb) guruInDb.password = baru;
        }
        saveDataToLocalStorage();
      }

      // Sync ke MySQL Server API
      const userId = (currentLoggedInUser && currentLoggedInUser.id) ? currentLoggedInUser.id : selectedGuruId;
      const res = await apiCall('change_password', { userId, oldPassword: lama, newPassword: baru });
      if (res && res.success && isServerOnline) {
        showToast(res.message || 'Kata sandi berhasil diperbarui di server MySQL!');
      } else {
        showToast('Kata sandi berhasil diperbarui!');
      }

      closeChangePasswordModal();
    }

    function showToast(msg, isError = false) {
      const toast = document.getElementById('toast');
      const toastMsg = document.getElementById('toast-msg');
      const toastIcon = document.getElementById('toast-icon');

      if (!toast) return;
      toastMsg.innerText = msg;
      if (isError) {
        toastIcon.className = 'fa-solid fa-triangle-exclamation text-rose-400';
      } else {
        toastIcon.className = 'fa-solid fa-check text-emerald-400';
      }

      toast.classList.remove('hidden');
      setTimeout(() => {
        toast.classList.add('hidden');
      }, 3000);
    }

