      const selMapel = document.getElementById('guru-filter-mapel');
      if (selMapel) {
        selMapel.innerHTML = '<option value="">Semua Mapel</option>' + MAPEL_LIST.map(m => `<option value="${m}">${m}</option>`).join('');
