      const selRekapSpv = document.getElementById('rekap-select-supervisor');
      if (selRekapSpv) {
        selRekapSpv.innerHTML = appSettings.supervisors.map(s => `<option value="${s.id}">${s.nama}</option>`).join('');
      }
    }


