    function renderUserManagement() {
      updateUserStats();
      populateUserSpvFilter();
      filterUserTable();
    }

    function updateUserStats() {
      const total = guruDatabase.length;
      const adminCount = guruDatabase.filter(g => g.is_superadmin).length;
      const spvCount = guruDatabase.filter(g => g.is_supervisor).length;
      const guruCount = guruDatabase.filter(g => !g.is_supervisor && !g.is_superadmin).length;

      const elTotal = document.getElementById('user-stat-total');
      const elAdmin = document.getElementById('user-stat-admin');
      const elSpv = document.getElementById('user-stat-spv');
      const elGuru = document.getElementById('user-stat-guru');

      if (elTotal) elTotal.innerText = total;
      if (elAdmin) elAdmin.innerText = adminCount;
      if (elSpv) elSpv.innerText = spvCount;
      if (elGuru) elGuru.innerText = guruCount;
    }

    function populateUserSpvFilter() {
      const sel = document.getElementById('user-filter-spv');
      if (!sel) return;
      const curVal = sel.value;
      sel.innerHTML = '<option value="">Semua Supervisor</option>' + appSettings.supervisors.map(s => `<option value="${s.id}" title="${s.nama}">${s.nama}</option>`).join('');
      sel.value = curVal;
    }

    function filterUserTable() {
      const q = (document.getElementById('user-search-input')?.value || '').toLowerCase();
      const roleFilter = document.getElementById('user-filter-role')?.value || '';
      const spvFilter = document.getElementById('user-filter-spv')?.value || '';

      const tbody = document.getElementById('user-table-tbody');
      if (!tbody) return;

      const filtered = guruDatabase.filter(g => {
        const matchSearch = g.nama.toLowerCase().includes(q) || g.nip.toLowerCase().includes(q) || g.mapel.toLowerCase().includes(q);
        let matchRole = true;
        if (roleFilter === 'superadmin') matchRole = !!g.is_superadmin;
        else if (roleFilter === 'supervisor') matchRole = !!g.is_supervisor;
        else if (roleFilter === 'guru') matchRole = !g.is_supervisor && !g.is_superadmin;

        let matchSpv = true;
        if (spvFilter !== '') matchSpv = (String(g.supervisorId) === String(spvFilter));

        return matchSearch && matchRole && matchSpv;
      });

      const countDisplay = document.getElementById('user-count-display');
      if (countDisplay) countDisplay.innerText = filtered.length;

      if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" class="py-8 text-center text-slate-400">Tidak ada akun pengguna yang sesuai dengan filter.</td></tr>`;
        return;
      }

      tbody.innerHTML = filtered.map((g, idx) => {
        const spv = appSettings.supervisors.find(s => s.id === g.supervisorId);
        const spvName = spv ? spv.nama.split('(')[0].trim() : '-';

        let roleBadges = '';
        if (g.is_superadmin) {
          roleBadges += `<span class="inline-block whitespace-nowrap px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-300 mr-1">Super Admin</span>`;
        }
        if (g.is_supervisor) {
          roleBadges += `<span class="inline-block whitespace-nowrap px-2 py-0.5 rounded text-[10px] font-bold bg-indigo-100 text-indigo-800 border border-indigo-200 mr-1">Supervisor</span>`;
        }
        if (!g.is_superadmin && !g.is_supervisor) {
          roleBadges += `<span class="inline-block whitespace-nowrap px-2 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-600 border border-slate-200">Guru Biasa</span>`;
        }

        return `
          <tr class="hover:bg-slate-50 transition">
            <td class="py-3 px-3.5 text-center font-medium text-slate-400 whitespace-nowrap">${idx + 1}</td>
            <td class="py-3 px-4 whitespace-nowrap">
              <div class="flex items-center space-x-2.5">
                <div class="w-7 h-7 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-xs flex-shrink-0 border border-indigo-100">
                  ${g.nama.charAt(0)}
                </div>
                <div>
                  <p class="font-bold text-slate-800 text-xs">${g.nama}</p>
                  <p class="text-[11px] font-mono text-slate-400">NIP: ${g.nip}</p>
                </div>
              </div>
            </td>
            <td class="py-3 px-4 whitespace-nowrap">
              <p class="font-medium text-slate-700 text-xs">${g.mapel}</p>
              <p class="text-[11px] text-slate-400">${g.kelas}</p>
            </td>
            <td class="py-3 px-4 whitespace-nowrap">${roleBadges}</td>
            <td class="py-3 px-4 whitespace-nowrap">
              <span class="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-medium bg-slate-50 text-slate-700 border border-slate-200">
                <i class="fa-solid fa-user-check text-indigo-500 mr-1"></i>
                ${spvName}
              </span>
            </td>
            <td class="py-3 px-4 text-center whitespace-nowrap">
              <button onclick="openResetPasswordModal(${g.id}, '${g.nama.replace(/'/g, "\'")}')" class="px-2.5 py-1 rounded bg-slate-100 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 text-slate-600 border border-slate-200 text-[11px] font-semibold transition" title="Reset Kata Sandi ke 123456">
                <i class="fa-solid fa-key mr-1 text-slate-400"></i>
                <span>Reset Sandi</span>
              </button>
            </td>
            <td class="py-3 px-4 text-right whitespace-nowrap">
              <div class="flex items-center justify-end space-x-1.5">
                <button onclick="openUserModal(${g.id})" class="p-1.5 rounded-lg bg-indigo-50 hover:bg-indigo-100 text-indigo-700 transition" title="Edit Akun & Peran">
                  <i class="fa-solid fa-pen-to-square text-xs"></i>
                </button>
                <button onclick="openDeleteUserModal(${g.id}, '${g.nama.replace(/'/g, "\'")}')" class="p-1.5 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-700 transition" title="Hapus Akun Pengguna">
                  <i class="fa-solid fa-trash-can text-xs"></i>
                </button>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }

    function openUserModal(id) {
      const modal = document.getElementById('modal-user-form');
      const title = document.getElementById('modal-user-form-title');
      const selSpv = document.getElementById('uf-supervisor');

      if (selSpv) {
        selSpv.innerHTML = appSettings.supervisors.map(s => `<option value="${s.id}">${s.nama}</option>`).join('');
      }

      if (id > 0) {
        const g = guruDatabase.find(x => x.id === id);
        if (!g) return;
        title.innerText = 'Edit Data & Hak Akses Pengguna';
        document.getElementById('uf-id').value = g.id;
        document.getElementById('uf-nama').value = g.nama;
        document.getElementById('uf-nip').value = g.nip;
        document.getElementById('uf-mapel').value = g.mapel;
        document.getElementById('uf-kelas').value = g.kelas;
        document.getElementById('uf-supervisor').value = g.supervisorId || 1;
        document.getElementById('uf-target').value = g.targetPerilaku || 'Instruksi Pembelajaran';
        document.getElementById('uf-is-supervisor').checked = !!g.is_supervisor;
        document.getElementById('uf-is-superadmin').checked = !!g.is_superadmin;
        document.getElementById('uf-password').value = '';
        document.getElementById('uf-pass-label').innerText = 'Ganti Kata Sandi (Opsional)';
      } else {
        title.innerText = 'Tambah Pengguna Baru';
        document.getElementById('uf-id').value = '0';
        document.getElementById('uf-nama').value = '';
        document.getElementById('uf-nip').value = '';
        document.getElementById('uf-mapel').value = '';
        document.getElementById('uf-kelas').value = '';
        document.getElementById('uf-supervisor').value = 1;
        document.getElementById('uf-target').value = 'Instruksi Pembelajaran';
        document.getElementById('uf-is-supervisor').checked = false;
        document.getElementById('uf-is-superadmin').checked = false;
        document.getElementById('uf-password').value = '123456';
        document.getElementById('uf-pass-label').innerText = 'Kata Sandi Awal';
      }

      modal.classList.remove('hidden');
    }

    function closeUserModal() {
      document.getElementById('modal-user-form')?.classList.add('hidden');
    }

    async function submitUserForm() {
      const id = parseInt(document.getElementById('uf-id').value) || 0;
      const nama = document.getElementById('uf-nama').value.trim();
      const nip = document.getElementById('uf-nip').value.trim();
      const mapel = document.getElementById('uf-mapel').value.trim() || 'Umum';
      const kelas = document.getElementById('uf-kelas').value.trim() || 'Kelas 7';
      const supervisorId = parseInt(document.getElementById('uf-supervisor').value) || 1;
      const targetPerilaku = document.getElementById('uf-target').value;
      const is_supervisor = document.getElementById('uf-is-supervisor').checked ? 1 : 0;
      const is_superadmin = document.getElementById('uf-is-superadmin').checked ? 1 : 0;
      const password = document.getElementById('uf-password').value.trim();

      if (!nama || !nip) {
        alert('Nama lengkap dan NIP wajib diisi!');
        return;
      }

      const payload = {
        id, nama, nip, mapel, kelas, supervisorId, targetPerilaku, is_supervisor, is_superadmin, password
      };

      if (id > 0) {
        const idx = guruDatabase.findIndex(x => x.id === id);
        if (idx !== -1) {
          guruDatabase[idx] = {
            ...guruDatabase[idx],
            nama, nip, mapel, kelas, supervisorId, targetPerilaku, is_supervisor, is_superadmin
          };
          if (password) guruDatabase[idx].password = password;
        }
      } else {
        const newId = Math.max(...guruDatabase.map(x => x.id), 0) + 1;
        guruDatabase.push({
          id: newId,
          nama, nip, mapel, kelas, supervisorId, targetPerilaku, is_supervisor, is_superadmin,
          password: password || '123456',
          status: 'Belum',
          materiTopik: '',
          tujuanPembelajaran: '',
          tanggalTelaah: '',
          rppScores: {},
          bkScores: {},
          bkDlScores: {},
          bkDlNotes: {},
          praFeedback: {},
          catatanPra: '',
          obsScores: {},
          obsNotes: [],
          deepLearning: { mindful: 0, meaningful: 0, joyful: 0, memahami: 0, mengaplikasi: 0, merefleksi: 0 },
          catatanFakta: '',
          tanggalObservasi: '',
          coaching: { tujuan: '', identifikasi: '', rencana: '', tanggungJawab: '' }
        });
      }

      saveDataToLocalStorage();
      populateDropdowns();
      filterGuruTable();
      renderUserManagement();
      closeUserModal();

      try {
        const res = await apiCall('save_user', payload);
        if (res && res.success) {
          showToast(res.message || 'Data pengguna berhasil disimpan ke server!');
          if (res.newId && id === 0) {
            guruDatabase[guruDatabase.length - 1].id = res.newId;
            saveDataToLocalStorage();
            filterUserTable();
          }
        } else if (res && res.error) {
          alert(res.error);
        }
      } catch(e) {
        console.warn('Simpan user offline', e);
      }
    }

    function openResetPasswordModal(id, nama) {
      document.getElementById('reset-user-id').value = id;
      document.getElementById('reset-user-nama').innerText = nama;
      document.getElementById('modal-user-reset-pwd')?.classList.remove('hidden');
    }

    function closeResetPasswordModal() {
      document.getElementById('modal-user-reset-pwd')?.classList.add('hidden');
    }

    async function confirmResetPassword() {
      const id = parseInt(document.getElementById('reset-user-id').value);
      if (!id) return;
      const g = guruDatabase.find(x => x.id === id);
      if (g) g.password = '123456';
      saveDataToLocalStorage();
      closeResetPasswordModal();
      showToast(`Kata sandi ${g ? g.nama : 'user'} berhasil direset ke '123456'!`);

      try {
        await apiCall('reset_password_admin', { id, password: '123456' });
      } catch(e) {}
    }

    function openDeleteUserModal(id, nama) {
      document.getElementById('delete-user-id').value = id;
      document.getElementById('delete-user-nama').innerText = nama;
      document.getElementById('modal-user-delete')?.classList.remove('hidden');
    }

    function closeDeleteUserModal() {
      document.getElementById('modal-user-delete')?.classList.add('hidden');
    }

    async function confirmDeleteUser() {
      const id = parseInt(document.getElementById('delete-user-id').value);
      if (!id) return;
      const idx = guruDatabase.findIndex(x => x.id === id);
      if (idx !== -1) {
        const deletedName = guruDatabase[idx].nama;
        guruDatabase.splice(idx, 1);
        saveDataToLocalStorage();
        populateDropdowns();
        filterGuruTable();
        renderUserManagement();
        closeDeleteUserModal();
        showToast(`Akun ${deletedName} berhasil dihapus.`);

        try {
          await apiCall('delete_user_admin', { id });
        } catch(e) {}
      }
    }

    window.onload = async function() {
      // 1. Muat database & settings dari localStorage terlebih dahulu
      const hasSaved = loadDataFromLocalStorage();
      if (!hasSaved || !guruDatabase || guruDatabase.length === 0) {
        generateInitialGuru();
        saveDataToLocalStorage();
      }

      // 2. Segera muat session login user dari localStorage (Anti-logout saat refresh!)
      const savedUser = loadUserSession();
      if (savedUser) {
        document.getElementById('modal-login')?.classList.add('hidden');
      }

      // 3. Fetch data terkini langsung dari server MySQL REST API
      try {
        const res = await apiCall('get_data');
        if (res && res.success) {
          if (res.appSettings) appSettings = res.appSettings;
          if (res.guruDatabase && res.guruDatabase.length > 0) {
            guruDatabase = res.guruDatabase;
          }
          saveDataToLocalStorage();

          // Jika server mengembalikan session login, sinkronkan ke local
          if (res.currentUser) {
            saveUserSession(res.currentUser);
          }
        }
      } catch (e) {
        console.warn('Init fetch offline', e);
      }

      populateDropdowns();

      document.getElementById('set-sekolah').value = appSettings.sekolah;
      document.getElementById('set-periode').value = appSettings.periode;
      document.getElementById('set-ks-nama').value = appSettings.kepalaSekolah.nama;
      document.getElementById('set-ks-nip').value = appSettings.kepalaSekolah.nip;
      const pNamaEl = document.getElementById('set-pengawas-nama');
      const pNipEl = document.getElementById('set-pengawas-nip');
      if (pNamaEl) pNamaEl.value = (appSettings.pengawasSekolah && appSettings.pengawasSekolah.nama) ? appSettings.pengawasSekolah.nama : 'Drs. Mochamad Solikin';
      if (pNipEl) pNipEl.value = (appSettings.pengawasSekolah && appSettings.pengawasSekolah.nip) ? appSettings.pengawasSekolah.nip : '196808061998021005';
      renderSupervisorInputs();

      const schoolNameSide = document.getElementById('sidebar-sekolah-nama');
      if (schoolNameSide) schoolNameSide.innerText = appSettings.sekolah;

      // 4. Periksa status login user
      if (currentLoggedInUser) {
        // Sembunyikan popup login
        document.getElementById('modal-login')?.classList.add('hidden');

        // Terapkan role switcher dan role aktif
        const activeRole = currentLoggedInUser.active_role || (currentLoggedInUser.available_roles ? currentLoggedInUser.available_roles[0] : 'guru');
        renderRoleSwitcher(currentLoggedInUser.available_roles || ['guru']);
        switchRole(activeRole);

        // Restore guru yang dipilih
        if (activeRole === 'guru' && currentLoggedInUser.id) {
          syncSelectedGuru(currentLoggedInUser.id);
        } else {
          const savedGid = localStorage.getItem(STORAGE_KEY_SELECTED_GURU);
          const gid = savedGid ? parseInt(savedGid) : (guruDatabase[0]?.id || 1);
          syncSelectedGuru(gid);
        }

        // Restore halaman/tab yang sedang dibuka sebelum refresh
        const savedView = localStorage.getItem(STORAGE_KEY_VIEW) || 'dashboard';
        navigateTo(savedView);
      } else {
        const defaultGuruId = (guruDatabase && guruDatabase.length > 0) ? guruDatabase[0].id : 1;
        syncSelectedGuru(defaultGuruId);
        showLoginModal();
        navigateTo('dashboard');
      }
    };
  </script>
</body>
</html>